        { status: authCheck.status || 401 }
      );
    }

    if (!adminDb) {
      return NextResponse.json({ success: false, message: 'Database not initialized' }, { status: 500 });
    }

    const docSnap = await adminDb.collection('site_settings').doc('notification_gateway').get();

    if (docSnap.exists) {
