      emailOnStatusChange: true,
      emailOnPasswordReset: true,
    };

    return NextResponse.json({ success: true, settings: defaultData, source: 'default' });
  } catch (error: any) {
    return NextResponse.json({ success: false, error: error.message }, { status: 500 });
