import { NextRequest, NextResponse } from 'next/server';
import crypto from 'crypto';
import { adminDb } from '@/lib/firebaseAdmin';
import { sendServerEmail, sendServerSms } from '@/lib/serverNotifications';
import { rateLimit, getClientIp } from '@/lib/rateLimit';
import { escapeHtml } from '@/lib/utils';

export async function POST(req: NextRequest) {
  const clientIp = getClientIp(req);
  const isAllowed = rateLimit(`pw_reset_req:${clientIp}`, 5, 15 * 60 * 1000);
  if (!isAllowed.ok) {
    return NextResponse.json(
      { error: 'Too many requests' },
      { status: 429 }
    );
  }

  try {
    const { email } = await req.json();
    const emailLower = (email || '').toLowerCase().trim();

    if (!emailLower || !emailLower.includes('@')) {
      return NextResponse.json(
        { success: false, error: 'Please enter a valid email address.' },
        { status: 400 }
      );
    }

    if (!adminDb) {
      return NextResponse.json(
        { success: false, error: 'Database service unavailable.' },
        { status: 500 }
      );
    }

    const userRef = adminDb.collection('users').doc(emailLower);
    const userSnap = await userRef.get();

    // Prevent user enumeration: respond with success even if account doesn't exist
    if (!userSnap.exists) {
      return NextResponse.json({
        success: true,
        message: 'If an account exists with this email, a verification code has been dispatched.',
      });
    }

    const userData = userSnap.data() || {};
    const resetCode = Math.floor(100000 + Math.random() * 900000).toString();
    const resetCodeHash = crypto.createHash('sha256').update(resetCode).digest('hex');
    const resetCodeExpiresAt = Date.now() + 10 * 60 * 1000; // 10 minutes expiry

    // Store only the secure hash and reset attempt counter (not plaintext)
    await userRef.update({
      resetCodeHash,
      resetCode: null, // Wipe any legacy plaintext code
      resetCodeExpiresAt,
      resetCodeAttempts: 0,
      updatedAt: new Date().toISOString(),
    });

    // Dispatch secure server-side OTP email
    const emailHtml = `
      <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 500px; margin: auto; padding: 24px; border: 1px solid #e4e4e7; border-radius: 16px; background-color: #ffffff;">
        <div style="text-align: center; margin-bottom: 20px;">
          <h2 style="color: #D12929; margin: 0; font-size: 22px;">MAGMATI Lifestyle</h2>
          <p style="color: #71717a; font-size: 13px; margin: 4px 0 0;">Password Reset Verification Code</p>
        </div>
        <p style="font-size: 14px; color: #18181b;">Hello <strong>${escapeHtml(userData.name || 'Valued Customer')}</strong>,</p>
        <p style="font-size: 14px; color: #52525b; line-height: 1.5;">We received a request to reset your MAGMATI account password. Please use the 6-digit verification code below to complete your reset:</p>
        <div style="text-align: center; margin: 24px 0;">
          <div style="display: inline-block; font-size: 32px; font-weight: 800; letter-spacing: 6px; color: #D12929; background-color: #fef2f2; padding: 12px 28px; border-radius: 12px; border: 1px dashed #fca5a5;">
            ${escapeHtml(resetCode)}
          </div>
        </div>
        <p style="font-size: 12px; color: #a1a1aa; text-align: center;">This code will expire in 10 minutes. If you did not make this request, you can safely ignore this email.</p>
      </div>
    `;

    await sendServerEmail({
      to: emailLower,
      subject: 'Your MAGMATI Password Reset Verification Code',
      html: emailHtml,
      text: `Your MAGMATI verification code is: ${resetCode}. Valid for 10 minutes.`,
    });

    if (userData.phone) {
      await sendServerSms({
        phone: userData.phone,
        message: `Your MAGMATI password reset code is: ${resetCode}. Valid for 10 minutes. Do not share this code with anyone.`,
        type: 'otp_verification',
      });
    }

    return NextResponse.json({
      success: true,
      message: 'Verification code sent successfully.',
    });
  } catch (error: any) {
    console.error('Password reset request error:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to process password reset request.' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import crypto from 'crypto';
import { adminDb, adminAuth } from '@/lib/firebaseAdmin';
import { rateLimit, getClientIp } from '@/lib/rateLimit';

const MAX_VERIFY_ATTEMPTS = 5;

export async function POST(req: NextRequest) {
  const clientIp = getClientIp(req);
  const isAllowed = rateLimit(`pw_reset_ver:${clientIp}`, 10, 15 * 60 * 1000);
  if (!isAllowed.ok) {
    return NextResponse.json(
      { error: 'Too many requests' },
      { status: 429 }
    );
  }

  try {
    const { email, resetCode, newPassword } = await req.json();
    const emailLower = (email || '').toLowerCase().trim();
    const codeClean = (resetCode || '').toString().trim();

    if (!emailLower || !codeClean || !newPassword) {
      return NextResponse.json(
        { success: false, error: 'Email, verification code, and new password are required.' },
        { status: 400 }
      );
    }

    if (newPassword.length < 6) {
      return NextResponse.json(
        { success: false, error: 'Password must be at least 6 characters long.' },
        { status: 400 }
      );
    }

    if (!adminDb || !adminAuth) {
      return NextResponse.json(
        { success: false, error: 'Authentication service unavailable.' },
        { status: 500 }
      );
    }

    const inputHash = crypto.createHash('sha256').update(codeClean).digest('hex');
    const userRef = adminDb.collection('users').doc(emailLower);

    // 1. Atomic Transaction to check attempts, verify hash, enforce expiry, and invalidate reset code
    await adminDb.runTransaction(async (transaction) => {
      const userDoc = await transaction.get(userRef);

      if (!userDoc.exists) {
        throw new Error('User account not found.');
      }

      const userData = userDoc.data() || {};
      const storedHash = userData.resetCodeHash;
      const legacyCode = userData.resetCode;
      const expiresAt = Number(userData.resetCodeExpiresAt);
      const currentAttempts = Number(userData.resetCodeAttempts || 0);

      if ((!storedHash && !legacyCode) || !expiresAt) {
        throw new Error('No active password reset code found. Please request a new code.');
      }

      if (Date.now() > expiresAt) {
        // Expired -> Invalidate
        transaction.update(userRef, {
          resetCodeHash: null,
          resetCode: null,
          resetCodeExpiresAt: null,
          resetCodeAttempts: null,
        });
        throw new Error('Verification code has expired. Please request a new code.');
      }

      if (currentAttempts >= MAX_VERIFY_ATTEMPTS) {
        // Exceeded maximum attempts -> Invalidate immediately
        transaction.update(userRef, {
          resetCodeHash: null,
          resetCode: null,
          resetCodeExpiresAt: null,
          resetCodeAttempts: null,
        });
        throw new Error('Maximum verification attempts exceeded. This code has been invalidated. Please request a new code.');
      }

      // Check match against SHA-256 hash or legacy plaintext
      const isMatched = storedHash === inputHash || (legacyCode && legacyCode.toString().trim() === codeClean);

      if (!isMatched) {
        const nextAttempts = currentAttempts + 1;
        const attemptsLeft = MAX_VERIFY_ATTEMPTS - nextAttempts;

        if (nextAttempts >= MAX_VERIFY_ATTEMPTS) {
          transaction.update(userRef, {
            resetCodeHash: null,
            resetCode: null,
            resetCodeExpiresAt: null,
            resetCodeAttempts: null,
          });
          throw new Error('Incorrect code. Maximum attempts reached. Code has been invalidated.');
        } else {
          transaction.update(userRef, {
            resetCodeAttempts: nextAttempts,
          });
          throw new Error(`Invalid verification code. ${attemptsLeft} attempt${attemptsLeft === 1 ? '' : 's'} remaining.`);
        }
      }

      // Match verified! Invalidate reset code (single-use)
      transaction.update(userRef, {
        resetCodeHash: null,
        resetCode: null,
        resetCodeExpiresAt: null,
        resetCodeAttempts: null,
        updatedAt: new Date().toISOString(),
      });
    });

    // 2. Authoritative Password Update in Firebase Authentication (Must not fail silently)
    try {
      const userRecord = await adminAuth.getUserByEmail(emailLower);
      if (userRecord?.uid) {
        await adminAuth.updateUser(userRecord.uid, { password: newPassword });
      }
    } catch (fbErr: any) {
      if (fbErr.code === 'auth/user-not-found') {
        try {
          await adminAuth.createUser({ email: emailLower, password: newPassword });
        } catch (createErr: any) {
          return NextResponse.json(
            { success: false, error: 'Failed to update authentication credentials: ' + (createErr.message || 'Auth error') },
            { status: 500 }
          );
        }
      } else {
        return NextResponse.json(
          { success: false, error: 'Failed to update authentication credentials: ' + (fbErr.message || 'Auth error') },
          { status: 500 }
        );
      }
    }

    return NextResponse.json({
      success: true,
      message: 'Password reset successfully. You can now log in with your new password.',
    });
  } catch (error: any) {
    return NextResponse.json(
      { success: false, error: error.message || 'Failed to verify password reset code.' },
      { status: 400 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminAuth, adminDb } from '@/lib/firebaseAdmin';
import { rateLimit, getClientIp } from '@/lib/rateLimit';

export const dynamic = 'force-dynamic';

/**
 * @api {post} /api/auth/sync-role Sync User Role
 * @description Verifies the Firebase ID token and returns the authoritative role from the server.
 */
export async function POST(req: NextRequest) {
  const clientIp = getClientIp(req);

  // Rate limit: 20 requests per minute per IP for role syncing
  const limitResult = rateLimit(`sync_role:${clientIp}`, 20, 60 * 1000);
  if (!limitResult.ok) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  const authHeader = req.headers.get('authorization') || req.headers.get('Authorization');
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return NextResponse.json({ error: 'Missing or invalid authorization header' }, { status: 401 });
  }

  const token = authHeader.substring(7).trim();
  if (!token) {
    return NextResponse.json({ error: 'Token is required' }, { status: 401 });
  }

  try {
    // 1. Verify token with Firebase Admin SDK
    const decoded = await adminAuth.verifyIdToken(token);
    if (!decoded || !decoded.email) {
      return NextResponse.json({ error: 'Invalid token payload' }, { status: 401 });
    }

    const email = decoded.email.toLowerCase();
    let role: 'admin' | 'customer' = 'customer';
    let reason:
      | 'admin_env_match'
      | 'admin_env_match_unverified_denied'
      | 'admin_firestore_role'
      | 'not_verified'
      | 'not_in_env_and_db_unavailable'
      | 'not_in_env_and_not_admin_in_db'
      | 'env_missing' = 'not_verified';

    const signInProvider = decoded.firebase?.sign_in_provider;
    const isEmailVerified = decoded.email_verified === true;
    const isGoogle = signInProvider === 'google.com';
    const isStrictVerified = isEmailVerified || isGoogle;

    const rawEnv = process.env.ADMIN_EMAILS;
    const isEnvSet = typeof rawEnv === 'string' && rawEnv.trim().length > 0;
    const adminEmails = (rawEnv || '')
      .split(',')
      .map((e) => e.trim().toLowerCase())
      .filter(Boolean);
    const isInAdminEmails = adminEmails.includes(email);

    // Admin role policy:
    // Grant admin if email is in ADMIN_EMAILS AND (email is verified OR provider is google.com).
    // Password login alone does NOT prove email ownership, so verification is required even for ADMIN_EMAILS.
    // The Firestore users/{email}.role === 'admin' path strictly requires verified email or google.com.
    // Anonymous or any other provider never gets admin.
    if (isInAdminEmails) {
      if (isStrictVerified) {
        role = 'admin';
        reason = 'admin_env_match';
      } else {
        role = 'customer';
        reason = 'admin_env_match_unverified_denied';
      }
    } else if (isStrictVerified) {
      if (!adminDb) {
        role = 'customer';
        reason = isEnvSet ? 'not_in_env_and_db_unavailable' : 'env_missing';
      } else {
        try {
          const userSnap = await adminDb.collection('users').doc(email).get();
          if (userSnap.exists && userSnap.data()?.role === 'admin') {
            role = 'admin';
            reason = 'admin_firestore_role';
          } else {
            role = 'customer';
            reason = isEnvSet ? 'not_in_env_and_not_admin_in_db' : 'env_missing';
          }
        } catch (dbErr: any) {
          console.error('[SyncRole] Firestore role lookup error:', dbErr.message || dbErr);
          role = 'customer';
          reason = isEnvSet ? 'not_in_env_and_db_unavailable' : 'env_missing';
        }
      }
    } else {
      role = 'customer';
      reason = 'not_verified';
    }

    // Server-side audit log (no secrets or tokens logged)
    console.log('[SyncRole Decision]', { role, reason });

    const responsePayload: { role: string; reason?: string } = { role };
    if (process.env.NODE_ENV !== 'production') {
      responsePayload.reason = reason;
    }

    return NextResponse.json(responsePayload);
  } catch (error: any) {
    console.error('Role sync error:', error);
    return NextResponse.json(
      { error: 'Token verification failed', details: error.message },
      { status: 401 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { verifyAdminServerSide } from '@/lib/serverAuth';
import { sendServerEmail } from '@/lib/serverNotifications';

interface EmailRequestBody {
  to: string;
  subject: string;
  html?: string;
  text?: string;
  orderId?: string;
}

export async function POST(req: NextRequest) {
  try {
    const authCheck = await verifyAdminServerSide(req);
    if (!authCheck.authorized) {
      return NextResponse.json(
        { success: false, error: authCheck.error || 'Unauthorized: Admin privileges required.' },
        { status: 401 }
      );
    }

    const body: EmailRequestBody = await req.json();
    const { to, subject, html, text, orderId } = body;

    if (!to || (!html && !text)) {
      return NextResponse.json({
        success: false,
        skipped: true,
        reason: 'Recipient email address or content was missing.',
      }, { status: 400 });
    }

    const result = await sendServerEmail({ to, subject, html, text, orderId });

    return NextResponse.json({
      success: result.success,
      skipped: result.skipped,
      reason: result.reason,
      recipient: to,
    }, { status: 200 });
  } catch (error: any) {
    console.warn('Admin email route handled error safely:', error?.message);
    return NextResponse.json({
      success: false,
      safeFail: true,
      error: error?.message || 'Failed to dispatch email.',
    }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { verifyAdminServerSide } from '@/lib/serverAuth';
import { sendServerSms } from '@/lib/serverNotifications';

interface SmsRequestBody {
  phone: string;
  message: string;
  type?: 'order_placed' | 'status_change' | 'otp_verification' | 'test_message';
  orderId?: string;
}

export async function POST(req: NextRequest) {
  try {
    const authCheck = await verifyAdminServerSide(req);
    if (!authCheck.authorized) {
      return NextResponse.json(
        { success: false, error: authCheck.error || 'Unauthorized: Admin privileges required.' },
        { status: 401 }
      );
    }

    const body: SmsRequestBody = await req.json();
    const { phone, message, type = 'test_message', orderId } = body;

    if (!phone || !message) {
      return NextResponse.json({
        success: false,
        skipped: true,
        reason: 'Phone number or message content was missing.',
      }, { status: 400 });
    }

    const result = await sendServerSms({ phone, message, orderId, type });

    return NextResponse.json({
      success: result.success,
      skipped: result.skipped,
      reason: result.reason,
      phone,
    }, { status: 200 });
  } catch (error: any) {
    console.warn('Admin SMS route handled error safely:', error?.message);
    return NextResponse.json({
      success: false,
      safeFail: true,
      error: error?.message || 'Failed to dispatch SMS.',
    }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb, adminAuth, isAdminDbReady } from '@/lib/firebaseAdmin';
import { BANGLADESH_DISTRICTS } from '@/lib/bangladeshDistricts';
import { FREE_SHIPPING_THRESHOLD_BDT, STANDARD_DELIVERY_DHAKA, STANDARD_DELIVERY_OUTSIDE, AUTO_DISCOUNT_MIN_BDT, AUTO_DISCOUNT_BDT } from '@/lib/constants';
import { dispatchServerOrderPlacedNotification } from '@/lib/serverNotifications';
import { products as initialMasterProducts } from '@/data/products';
import { rateLimit, getClientIp } from '@/lib/rateLimit';

interface CreateOrderRequestBody {
  userEmail?: string;
  userName: string;
  phone: string;
  address: string;
  district?: string;
  orderNotes?: string;
  payment: string;
  trxId?: string;
  items: Array<{
    product: { id: string; name?: string; price?: number; image?: string; category?: string };
    quantity: number;
    selectedSize?: string;
    selectedColor?: { name: string; hex: string };
    customPrice?: number;
    isFreeItem?: boolean;
    isComboItem?: boolean;
    comboId?: string;
    promoLabel?: string;
  }>;
  appliedCoupon?: string;
}

export async function POST(req: NextRequest) {
  const clientIp = getClientIp(req);
  const isAllowed = rateLimit(`order_create:${clientIp}`, 10, 60 * 1000);
  if (!isAllowed.ok) {
    return NextResponse.json(
      { error: 'Too many requests' },
      { status: 429 }
    );
  }

  try {
    const body: CreateOrderRequestBody = await req.json();

    if (isAdminDbReady === false) {
      console.error('[OrderCreate] Rejected: adminDb is not ready. Missing FIREBASE_SERVICE_ACCOUNT_KEY or ADC.');
      return NextResponse.json(
        { success: false, error: 'Server database is not configured. Order was NOT saved. Please contact support.' },
        { status: 503 }
      );
    }

    const {
      userEmail: clientEmail,
      userName,
      phone,
      address,
      district = 'dhaka',
      orderNotes = '',
      payment = 'Cash on Delivery',
      trxId = '',
      items = [],
      appliedCoupon,
    } = body;

    // 1. Field validation
    if (!userName || !phone || !address || !items || items.length === 0) {
      return NextResponse.json(
        { success: false, error: 'Missing required order details (Name, Phone, Address, or Items).' },
        { status: 400 }
      );
    }

    const cleanedPhone = phone.replace(/[\s-+]/g, '').replace(/^88/, '');
    if (!/^01[3-9]\d{8}$/.test(cleanedPhone)) {
      return NextResponse.json(
        { success: false, error: 'Please enter a valid 11-digit Bangladeshi mobile number.' },
        { status: 400 }
      );
    }

    // 2. Order Identity Verification: derive authenticated identity from Bearer token if present
    let verifiedUserEmail = (clientEmail || '').toLowerCase().trim();
    const authHeader = req.headers.get('authorization') || req.headers.get('Authorization');

    if (authHeader && authHeader.startsWith('Bearer ') && adminAuth) {
      try {
        const token = authHeader.substring(7).trim();
        const decoded = await adminAuth.verifyIdToken(token);
        if (decoded?.email) {
          verifiedUserEmail = decoded.email.toLowerCase().trim();
        }
      } catch {
        // Fallback to provided guest email
      }
    }

    // 3. Authoritative Server Product Pricing & Stock Validation
    let siteSettingsData: any = null;
    if (adminDb) {
      try {
        const settingsDoc = await adminDb.collection('site_settings').doc('general').get();
        if (settingsDoc.exists) {
          siteSettingsData = settingsDoc.data();
        }
      } catch {}
    }
    const activeB1g1Offers = siteSettingsData?.b1g1Offers || [
      {
        id: 'b1g1-demo-1',
        buyProductId: 'elec-ultra-watch-pro',
        getProductId: 'elec-bluetooth-speaker',
        enabled: true,
      }
    ];
    const activeCombos = siteSettingsData?.combos || [
      {
        id: 'combo-demo-1',
        comboPrice: 2490,
        enabled: true,
        items: [
          { productId: 'elec-rgb-headset', quantity: 1 },
          { productId: 'elec-wireless-mouse', quantity: 1 },
        ],
      }
    ];

    let verifiedSubtotal = 0;
    const verifiedOrderItems: any[] = [];

    for (const item of items) {
      const prodId = item.product?.id;
      if (!prodId) {
        return NextResponse.json(
          { success: false, error: 'Invalid order item: missing product ID.' },
          { status: 400 }
        );
      }

      let prodData: any = null;

      // Try Firestore lookup first if adminDb is available
      if (adminDb) {
        try {
          const prodDoc = await adminDb.collection('products').doc(prodId).get();
          if (prodDoc.exists) {
            prodData = prodDoc.data();
          }
        } catch {
          // Fallback to master catalog
        }
      }

      // If not found in Firestore, resolve from master product catalog
      if (!prodData) {
        const catalogProd = initialMasterProducts.find((p) => p.id === prodId);
        if (catalogProd) {
          prodData = {
            id: catalogProd.id,
            name: catalogProd.name,
            price: catalogProd.price,
            stockQuantity: catalogProd.stockQuantity ?? 50,
            images: catalogProd.images,
            category: catalogProd.category,
          };
        }
      }

      // Reject if product does not exist in authoritative server catalog (no client price fallback)
      if (!prodData) {
        return NextResponse.json(
          { success: false, error: `Product "${prodId}" does not exist in the authoritative product catalog.` },
          { status: 400 }
        );
      }

      const authoritativePrice = typeof prodData.price === 'number' ? prodData.price : 0;
      const qty = Math.max(1, Math.floor(Number(item.quantity) || 1));

      const availableStock = typeof prodData.stockQuantity === 'number' ? prodData.stockQuantity : 50;
      if (qty > availableStock) {
        return NextResponse.json(
          { success: false, error: `Sorry, product "${prodData.name || prodId}" only has ${availableStock} units left in stock.` },
          { status: 400 }
        );
      }

      // Calculate effective item price with strict server-side promotion validation
      let effectiveItemPrice = authoritativePrice;
      let isFreeItemVerified = false;
      let isComboItemVerified = false;

      if (item.isFreeItem) {
        const validOffer = activeB1g1Offers.find((offer: any) =>
          offer.enabled &&
          offer.getProductId === prodId
        );

        const qualifyingItem = items.find((i: any) =>
          (i.product?.id || i.productId) === validOffer?.buyProductId &&
          !i.isFreeItem &&
          Boolean(i.claimedB1G1 || i.claimedB1G1Offer)
        );

        if (validOffer && qualifyingItem) {
          const buyQty = validOffer.buyQuantity || 1;
          const getQty = validOffer.getQuantity || 1;
          const qualifyingQty = Math.max(1, Math.floor(Number(qualifyingItem.quantity) || 1));
          const maxFreeAllowed = Math.floor(qualifyingQty / buyQty) * getQty;

          if (qty <= maxFreeAllowed) {
            effectiveItemPrice = 0;
            isFreeItemVerified = true;
          } else {
            return NextResponse.json(
              { success: false, error: `Free gift quantity (${qty}) exceeds allowed offer quantity (${maxFreeAllowed}) for product "${prodId}".` },
              { status: 400 }
            );
          }
        } else {
          return NextResponse.json(
            { success: false, error: `Invalid or unauthorized free item claim for product "${prodId}". Qualifying product and explicit offer claim required.` },
            { status: 400 }
          );
        }
      } else if (item.isComboItem && item.comboId) {
        const validCombo = activeCombos.find((combo: any) =>
          combo.enabled &&
          combo.id === item.comboId &&
          combo.items?.some((ci: any) => ci.productId === prodId)
        );

        // Verify that ALL combo items are present in order payload for this combo
        const allComboItemsPresent = validCombo?.items?.every((ci: any) =>
          items.some((i: any) => (i.product?.id || i.productId) === ci.productId && i.isComboItem && i.comboId === validCombo.id)
        );

        if (validCombo && allComboItemsPresent) {
          // Calculate server-authoritative combo price allocation across combo items
          let comboOriginalSum = 0;
          const comboProductPrices: Record<string, number> = {};

          for (const ci of validCombo.items) {
            const catProd = initialMasterProducts.find((p) => p.id === ci.productId);
            const pPrice = catProd?.price || authoritativePrice;
            comboProductPrices[ci.productId] = pPrice;
            comboOriginalSum += pPrice * (ci.quantity || 1);
          }

          let allocatedComboPrice = validCombo.comboPrice;
          if (comboOriginalSum > 0) {
            allocatedComboPrice = Math.round((authoritativePrice / comboOriginalSum) * validCombo.comboPrice);
          }

          effectiveItemPrice = allocatedComboPrice;
          isComboItemVerified = true;
        } else {
          return NextResponse.json(
            { success: false, error: `Invalid or manipulated combo promotion for product "${prodId}". All combo items must be present.` },
            { status: 400 }
          );
        }
      }

      verifiedSubtotal += effectiveItemPrice * qty;
      verifiedOrderItems.push({
        product: {
          id: prodId,
          name: prodData.name || 'Product',
          price: authoritativePrice,
          image: prodData.images?.[0] || prodData.image || '',
          category: prodData.category || '',
        },
        quantity: qty,
        selectedSize: item.selectedSize || 'Standard',
        selectedColor: item.selectedColor || { name: 'Standard', hex: '#000000' },
        customPrice: effectiveItemPrice,
        isFreeItem: isFreeItemVerified,
        isComboItem: isComboItemVerified,
        ...(item.comboId ? { comboId: item.comboId } : {}),
        ...(item.promoLabel ? { promoLabel: item.promoLabel } : {}),
      });
    }

    if (verifiedOrderItems.length === 0) {
      return NextResponse.json(
        { success: false, error: 'No valid product items in order.' },
        { status: 400 }
      );
    }

    // 4. Server-Side Delivery Fee Calculation
    const activeDistrict = BANGLADESH_DISTRICTS.find((d) => d.id === district || d.nameEn.toLowerCase() === district.toLowerCase());
    const isInsideDhaka = activeDistrict ? activeDistrict.isDhakaCity : true;

    const verifiedDeliveryFee = verifiedSubtotal >= FREE_SHIPPING_THRESHOLD_BDT
      ? 0
      : isInsideDhaka
      ? STANDARD_DELIVERY_DHAKA
      : STANDARD_DELIVERY_OUTSIDE;

    // 5. Server-Side Voucher Discount Calculation
    let verifiedDiscount = 0;
    if (appliedCoupon) {
      const codeClean = appliedCoupon.trim().toUpperCase();
      if (codeClean === 'MAGMA200') {
        if (verifiedSubtotal >= 1500) verifiedDiscount = 200;
      } else if (codeClean === 'FESTIVE500') {
        if (verifiedSubtotal >= AUTO_DISCOUNT_MIN_BDT) verifiedDiscount = AUTO_DISCOUNT_BDT;
      } else if (codeClean === 'EIDMEGA1000') {
        if (verifiedSubtotal >= 6000) verifiedDiscount = 1000;
      } else if (codeClean === 'WELCOME10' || codeClean === 'MAGMATI10') {
        verifiedDiscount = Math.round(verifiedSubtotal * 0.1);
      } else if (codeClean === 'FASHION15') {
        verifiedDiscount = Math.round(verifiedSubtotal * 0.15);
      } else if (codeClean === 'FREESHIP') {
        verifiedDiscount = verifiedDeliveryFee;
      }
    }

    const verifiedTotal = Math.max(0, verifiedSubtotal + verifiedDeliveryFee - verifiedDiscount);

    // 6. Generate Order Document
    const orderId = `MGM-${Math.floor(100000 + Math.random() * 900000)}`;
    const dateOptions: Intl.DateTimeFormatOptions = { day: '2-digit', month: 'short', year: 'numeric' };
    const currentDate = new Date().toLocaleDateString('en-US', dateOptions);
    const isoDate = new Date().toISOString();

    const verifiedOrderDocument = {
      id: orderId,
      userEmail: verifiedUserEmail,
      userName: userName.trim(),
      phone: cleanedPhone,
      address: address.trim(),
      district: activeDistrict ? activeDistrict.nameEn : 'Dhaka',
      orderNotes: orderNotes.trim(),
      payment,
      ...(trxId ? { trxId: trxId.trim() } : {}),
      items: verifiedOrderItems,
      subtotal: verifiedSubtotal,
      deliveryFee: verifiedDeliveryFee,
      discount: verifiedDiscount,
      total: verifiedTotal,
      status: 'Pending',
      date: currentDate,
      createdAt: isoDate,
    };

    // 7. Atomic Firestore Stock Deduction & Order Persistence (Strictly Transactional & Concurrency-Safe)
    if (adminDb) {
      try {
        const orderRef = adminDb.collection('orders').doc(orderId);
        await adminDb.runTransaction(async (transaction) => {
          for (const item of verifiedOrderItems) {
            const productRef = adminDb.collection('products').doc(item.product.id);
            const productSnap = await transaction.get(productRef);

            let stockNum = 50;
            let productExists = false;
            const catalogProd = initialMasterProducts.find((p) => p.id === item.product.id);

            if (productSnap.exists) {
              productExists = true;
              const currentStock = productSnap.data()?.stockQuantity;
              stockNum = typeof currentStock === 'number' ? currentStock : 50;
            } else if (catalogProd) {
              productExists = true;
              stockNum = typeof catalogProd.stockQuantity === 'number' ? catalogProd.stockQuantity : 50;
            }

            if (!productExists) {
              throw new Error(`Product "${item.product.id}" no longer exists.`);
            }

            if (stockNum < item.quantity) {
              throw new Error(`Insufficient stock for "${item.product.name || item.product.id}". Available: ${stockNum}, Requested: ${item.quantity}`);
            }

            const updatedStock = stockNum - item.quantity;

            if (productSnap.exists) {
              transaction.update(productRef, {
                stockQuantity: updatedStock,
                inStock: updatedStock > 0,
                updatedAt: isoDate,
              });
            } else if (catalogProd) {
              transaction.set(productRef, {
                id: catalogProd.id,
                name: catalogProd.name,
                slug: catalogProd.slug,
                price: catalogProd.price,
                originalPrice: catalogProd.originalPrice ?? null,
                discountPercent: catalogProd.discountPercent ?? null,
                category: catalogProd.category,
                subcategory: catalogProd.subcategory,
                images: catalogProd.images || [],
                sizes: catalogProd.sizes || [],
                colors: catalogProd.colors || [],
                description: catalogProd.description || '',
                details: catalogProd.details || [],
                brand: catalogProd.brand || 'MAGMATI',
                sku: catalogProd.sku || catalogProd.id,
                inStock: updatedStock > 0,
                stockQuantity: updatedStock,
                createdAt: isoDate,
                updatedAt: isoDate,
              });
            }
          }
          transaction.set(orderRef, verifiedOrderDocument);
        });
      } catch (adminErr: any) {
        if (adminErr.message && (adminErr.message.includes('Insufficient stock') || adminErr.message.includes('no longer exists.'))) {
          throw adminErr;
        }
        if (adminErr.message && adminErr.message.includes('PERMISSION_DENIED')) {
          for (const item of verifiedOrderItems) {
            const stockNum = 50;
            if (item.quantity > stockNum) {
              throw new Error(`Insufficient stock for "${item.product.name || item.product.id}". Available: ${stockNum}, Requested: ${item.quantity}`);
            }
          }
        } else {
          throw adminErr;
        }
      }
    }

    // 8. Dispatch Server-Side Order Placed Notifications
    dispatchServerOrderPlacedNotification(verifiedOrderDocument).catch((err) => {
      console.warn('Background order notification notice:', err);
    });

    return NextResponse.json({
      success: true,
      orderId,
      total: verifiedTotal,
      order: verifiedOrderDocument,
    });
  } catch (error: any) {
    console.error('Server order creation error:', error);
    const msg = error.message || 'Failed to create order.';
    const status = msg.includes('Insufficient stock') || msg.includes('no longer exists.') ? 400 : 500;
    return NextResponse.json(
      { success: false, error: msg },
      { status }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb, adminAuth } from '@/lib/firebaseAdmin';

export async function GET(req: NextRequest) {
  try {
    const authHeader = req.headers.get('authorization') || req.headers.get('Authorization');
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return NextResponse.json(
        { success: false, error: 'Unauthorized: Missing authentication token.' },
        { status: 401 }
      );
    }

    if (!adminAuth || !adminDb) {
      return NextResponse.json(
        { success: false, error: 'Database service unavailable.' },
        { status: 500 }
      );
    }

    const token = authHeader.substring(7).trim();
    let decoded: any = null;
    try {
      decoded = await adminAuth.verifyIdToken(token);
    } catch (verifyErr: any) {
      console.error('[OrderHistoryAPI] Token verification failed:', verifyErr?.message || verifyErr);
      return NextResponse.json(
        { success: false, error: 'Unauthorized: Invalid or expired authentication token.' },
        { status: 401 }
      );
    }

    if (!decoded || !decoded.email) {
      return NextResponse.json(
        { success: false, error: 'Unauthorized: Invalid authentication token.' },
        { status: 401 }
      );
    }

    const email = decoded.email.toLowerCase().trim();

    // Query orders for this user email securely
    let userOrders: any[] = [];
    try {
      const ordersSnap = await adminDb.collection('orders')
        .where('userEmail', '==', email)
        .get();

      ordersSnap.forEach((doc) => {
        userOrders.push({
          id: doc.id,
          ...doc.data()
        });
      });
    } catch (dbErr: any) {
      console.error('[OrderHistoryAPI] Firestore query failed:', dbErr?.message || dbErr);
      return NextResponse.json(
        { success: false, error: 'Failed to load orders.' },
        { status: 500 }
      );
    }

    // Sort newest first by createdAt timestamp
    userOrders.sort((a, b) => {
      const timeA = a.createdAt ? new Date(a.createdAt).getTime() : 0;
      const timeB = b.createdAt ? new Date(b.createdAt).getTime() : 0;
      return timeB - timeA;
    });

    return NextResponse.json({
      success: true,
      orders: userOrders,
    });
  } catch (error: any) {
    console.error(`[OrderHistoryAPI] Fetch error for user token query: ${error?.code || error?.message || error}`);
    return NextResponse.json(
      { success: false, error: error.message || 'Failed to fetch order history.' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebaseAdmin';
import { isPhoneMatching, isValidBDPhone } from '@/lib/phoneUtils';
import { rateLimit, getClientIp } from '@/lib/rateLimit';

export async function GET(req: NextRequest) {
  const clientIp = getClientIp(req);
  const isAllowed = rateLimit(`order_track:${clientIp}`, 30, 60 * 1000);
  if (!isAllowed.ok) {
    return NextResponse.json(
      { error: 'Too many requests' },
      { status: 429 }
    );
  }

  try {
    const { searchParams } = new URL(req.url);
    const orderId = (searchParams.get('orderId') || searchParams.get('id') || '').trim().toUpperCase();
    const phone = (searchParams.get('phone') || '').trim();

    if (!orderId || !phone || !isValidBDPhone(phone)) {
      return NextResponse.json(
        { success: false, error: 'Order ID and complete 11-digit matching phone number are required.' },
        { status: 400 }
      );
    }

    let data: any = null;

    if (adminDb) {
      const orderSnap = await adminDb.collection('orders').doc(orderId).get();
      if (orderSnap.exists) {
        data = orderSnap.data();
      }
    }

    if (!data) {
      return NextResponse.json({ success: false, error: 'No order found with the provided details.' }, { status: 404 });
    }

    const storedPhone = data.phone || '';

    // Verification check: ensure complete normalized phone equality (no endsWith or partial matching)
    if (!isPhoneMatching(storedPhone, phone)) {
      return NextResponse.json({ success: false, error: 'No order found with the provided details.' }, { status: 404 });
    }

    // Return minimum sanitized tracking fields only (exclude customer address, email, phone, PII)
    const sanitizedTrackingOrder = {
      id: data.id,
      status: data.status,
      date: data.date,
      createdAt: data.createdAt,
      total: data.total,
      payment: data.payment,
      items: Array.isArray(data.items)
        ? data.items.map((item: any) => ({
            product: {
              id: item.product?.id || '',
              name: item.product?.name || 'Product',
              image: item.product?.image || item.product?.images?.[0] || '',
            },
            quantity: item.quantity || 1,
            selectedSize: item.selectedSize || 'Standard',
            selectedColor: item.selectedColor || { name: 'Standard', hex: '#000000' },
            customPrice: item.customPrice,
            isFreeItem: Boolean(item.isFreeItem),
            isComboItem: Boolean(item.isComboItem),
          }))
        : [],
      courier: data.courier,
      courierBooked: Boolean(data.courierBooked),
      district: data.district,
    };

    return NextResponse.json({
      success: true,
      order: sanitizedTrackingOrder,
    });
  } catch (error: any) {
    return NextResponse.json({ success: false, error: error.message || 'Failed to track order.' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb, adminAuth } from '@/lib/firebaseAdmin';
import { verifyAdminServerSide } from '@/lib/serverAuth';
import { dispatchServerOrderStatusNotification } from '@/lib/serverNotifications';

const VALID_STATUSES = ['Pending', 'Processing', 'Shipped', 'Dispatched', 'Delivered', 'Cancelled'];

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { orderId, status } = body;

    if (!orderId || !status || !VALID_STATUSES.includes(status)) {
      return NextResponse.json(
        { success: false, error: 'Invalid order ID or status provided.' },
        { status: 400 }
      );
    }

    if (!adminDb) {
      return NextResponse.json(
        { success: false, error: 'Database service unavailable.' },
        { status: 500 }
      );
    }

    const orderRef = adminDb.collection('orders').doc(orderId);
    const orderSnap = await orderRef.get();

    if (!orderSnap.exists) {
      return NextResponse.json(
        { success: false, error: 'Order not found.' },
        { status: 404 }
      );
    }

    const orderData = orderSnap.data() || {};
    const previousStatus = orderData.status;

    // 1. Check Admin Authorization
    const adminCheck = await verifyAdminServerSide(req);
    const isAdmin = adminCheck.authorized;

    if (!isAdmin) {
      // Non-admins can ONLY cancel their own Pending order with a verified Firebase ID token
      if (status !== 'Cancelled') {
        return NextResponse.json(
          { success: false, error: 'Unauthorized: Only administrators can update orders to non-cancelled statuses.' },
          { status: 403 }
        );
      }

      if (previousStatus !== 'Pending') {
        return NextResponse.json(
          { success: false, error: `Order #${orderId} cannot be cancelled because it is already ${previousStatus}.` },
          { status: 400 }
        );
      }

      const orderEmail = (orderData.userEmail || '').toLowerCase().trim();
      let isOwnerVerified = false;

      // Authenticated customer ownership check: derive identity from verified Bearer token
      const authHeader = req.headers.get('authorization') || req.headers.get('Authorization');
      if (authHeader && authHeader.startsWith('Bearer ') && adminAuth) {
        try {
          const token = authHeader.substring(7).trim();
          const decoded = await adminAuth.verifyIdToken(token);
          if (decoded?.email && decoded.email.toLowerCase().trim() === orderEmail) {
            isOwnerVerified = true;
          }
        } catch {
          // Token verification failed
        }
      }

      // Fail closed: reject if not verified via valid Firebase ID token
      if (!isOwnerVerified) {
        return NextResponse.json(
          { success: false, error: 'Unauthorized: Order cancellation requires verified order ownership with a valid authentication token.' },
          { status: 401 }
        );
      }
    }

    // 2. Atomic Transaction: Update status + restore inventory if transitioning to Cancelled
    await adminDb.runTransaction(async (transaction) => {
      const currentDoc = await transaction.get(orderRef);
      if (!currentDoc.exists) {
        throw new Error('Order not found during transaction.');
      }

      const curData = currentDoc.data() || {};

      // If transitioning to Cancelled and was NOT already Cancelled, restock atomically
      if (status === 'Cancelled' && curData.status !== 'Cancelled' && Array.isArray(curData.items)) {
        for (const item of curData.items) {
          if (item.product?.id) {
            const productRef = adminDb.collection('products').doc(item.product.id);
            const productSnap = await transaction.get(productRef);
            if (productSnap.exists) {
              const currentStock = Number(productSnap.data()?.stockQuantity ?? 0);
              const newStock = currentStock + (Number(item.quantity) || 1);
              transaction.update(productRef, {
                stockQuantity: newStock,
                inStock: newStock > 0,
                updatedAt: new Date().toISOString(),
              });
            }
          }
        }
      }

      transaction.update(orderRef, {
        status,
        updatedAt: new Date().toISOString(),
      });
    });

    // 3. Trigger Server-Side Status Change Notification
    if (previousStatus !== status) {
      dispatchServerOrderStatusNotification(
        {
          id: orderId,
          userName: orderData.userName || 'Customer',
          phone: orderData.phone || '',
          userEmail: orderData.userEmail,
          status,
        },
        status
      ).catch((err) => {
        console.warn('Status notification dispatch notice:', err);
      });
    }

    return NextResponse.json({
      success: true,
      orderId,
      status,
    });
  } catch (error: any) {
    console.error('Order status update error:', error);
    return NextResponse.json(
      { success: false, error: error.message || 'Failed to update order status.' },
      { status: 500 }
    );
  }
}

