'use client';

import React, { useState } from 'react';
import { Database, Download, RotateCcw, CheckCircle2, Loader2 } from 'lucide-react';
import { ConfirmDialog } from '@/components/ui/ConfirmDialog';
import { exportFullStoreBackup } from '@/lib/dataTransferUtils';
import { useProductStore } from '@/store/useProductStore';
import { useOrderStore } from '@/store/useOrderStore';
import { useCategoryStore } from '@/store/useCategoryStore';
import { useVoucherStore } from '@/store/useVoucherStore';
import { useToastStore } from '@/store/useToastStore';

interface BackupResetSettingsProps {
  siteSettings: {
    resetSettings: () => void;
  };
}

export const BackupResetSettings: React.FC<BackupResetSettingsProps> = ({
  siteSettings,
}) => {
  const { addToast } = useToastStore();
  const [isBackingUp, setIsBackingUp] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const [confirmDialog, setConfirmDialog] = useState<{
    open: boolean;
    title: string;
    message: string;
    confirmLabel?: string;
    cancelLabel?: string;
    onConfirm: () => void | Promise<void>;
  }>({
    open: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });


  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex items-center justify-between pb-3 border-b border-zinc-100 flex-wrap gap-2">
        <div>
          <h4 className="font-bold text-text-main text-sm flex items-center gap-2">
            <Database className="w-4.5 h-4.5 text-primary" />
            <span>{'Full Store Backup & Maintenance'}</span>
          </h4>
          <p className="text-xs text-text-muted mt-0.5">
            {'Download complete JSON snapshots of your store or restore initial default presets.'}
          </p>
        </div>
      </div>

      <div className="p-5 bg-gradient-to-br from-zinc-50 to-zinc-100/80 rounded-2xl border border-border-color space-y-4 shadow-2xs">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center gap-3.5">
            <div className="w-12 h-12 rounded-2xl bg-surface-dark text-white flex items-center justify-center shadow-xs">
              <Database className="w-6 h-6 text-amber-400" />
            </div>
            <div>
              <h5 className="font-bold text-text-main text-sm">
                {'Export All-in-One Store Backup (.json)'}
              </h5>
              <p className="text-xs text-text-muted">
                {'Instant snapshot with all products, orders, categories, vouchers, and settings.'}
              </p>
            </div>
          </div>

          <button
            type="button"
            disabled={isBackingUp}
            onClick={async () => {
              setIsBackingUp(true);
              try {
                await new Promise((res) => setTimeout(res, 400));
                const products = useProductStore.getState().products;
                const orders = useOrderStore.getState().orders;
                const categories = useCategoryStore.getState().categories;
                const vouchers = useVoucherStore.getState().vouchers;
                exportFullStoreBackup({
                  products,
                  orders,
                  categories,
                  siteSettings,
                  vouchers,
                });
              } finally {
                setIsBackingUp(false);
              }
            }}
            className="px-4 py-2.5 bg-surface-dark hover:bg-zinc-800 text-white rounded-xl text-xs font-bold transition-all shadow-sm flex items-center gap-2 cursor-pointer shrink-0 disabled:opacity-60 disabled:cursor-not-allowed"
          >
            {isBackingUp ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin text-amber-400" />
                <span>Preparing Backup...</span>
              </>
            ) : (
              <>
                <Download className="w-4 h-4 text-amber-400" />
                <span>{'Download Backup (.json)'}</span>
              </>
            )}
          </button>
        </div>
      </div>

      {/* Reset Defaults Block */}
      <div className="p-5 rounded-2xl bg-red-50/60 border border-red-200 space-y-3">
        <div className="flex items-center justify-between flex-wrap gap-3">
          <div>
            <h5 className="font-bold text-red-900 text-xs sm:text-sm">
              {'Factory Defaults Reset'}
            </h5>
            <p className="text-2xs text-red-700/80">
              {'Reset all layout, shipping, banners, and store configurations to factory initial presets.'}
            </p>
          </div>

          <button
            type="button"
            disabled={isResetting}
            onClick={() => {
              setConfirmDialog({
                open: true,
                title: 'Reset All Site Settings to Factory Defaults',
                message: 'Are you sure you want to reset all layout, shipping, banners, and store configurations to factory initial presets? This action cannot be undone.',
                confirmLabel: 'Reset',
                cancelLabel: 'Cancel',
                onConfirm: async () => {
                  setIsResetting(true);
                  try {
                    siteSettings.resetSettings();
                    setConfirmDialog((prev) => ({ ...prev, open: false }));
                    addToast('All site settings & layouts successfully reset to factory defaults!', 'success');
                  } finally {
                    setIsResetting(false);
                  }
                },
              });
            }}
            className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-xl text-xs font-bold transition-all shadow-xs cursor-pointer flex items-center gap-1.5 disabled:opacity-60 disabled:cursor-not-allowed"
          >
            {isResetting ? (
              <Loader2 className="w-3.5 h-3.5 animate-spin" />
            ) : (
              <RotateCcw className="w-3.5 h-3.5" />
            )}
            <span>{'Reset Defaults'}</span>
          </button>
        </div>
      </div>


      {/* Shared Reset Confirmation Dialog */}
      <ConfirmDialog
        open={confirmDialog.open}
        title={confirmDialog.title}
        message={confirmDialog.message}
        variant="danger"
        confirmLabel={confirmDialog.confirmLabel}
        cancelLabel={confirmDialog.cancelLabel}
        loading={isResetting}
        onConfirm={confirmDialog.onConfirm}
        onCancel={() => setConfirmDialog((prev) => ({ ...prev, open: false }))}
      />
    </div>
  );
};

/**
 * @file components/admin/BestDealsTab.tsx
 * @description Master Admin HQ Management Tab for Best Deals Showcases.
 * Features:
 * - List all deal emporiums with thumbnail previews & live status
 * - Drag/order reordering (move up, move down)
 * - Add new section & Edit modal integration
 * - Quick toggle enabled/disabled
 * - Delete section & Restore Defaults
 */

'use client';

import React, { useState } from 'react';
import Image from 'next/image';
import Link from 'next/link';
import { 
  Flame, 
  Plus, 
  ArrowUp, 
  ArrowDown, 
  Edit3, 
  Trash2, 
  Eye, 
  RotateCcw, 
  ExternalLink,
  CheckCircle2,
  XCircle,
  Sparkles
} from 'lucide-react';
import { useBestDealsStore } from '@/store/useBestDealsStore';
import { BestDealSection } from '@/types/bestDeals';
import { BestDealSectionModal } from './modals/BestDealSectionModal';

export function BestDealsTab() {
  const { 
    sections, 
    addSection, 
    updateSection, 
    deleteSection, 
    toggleSection, 
    moveSection, 
    resetToDefault 
  } = useBestDealsStore();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingSection, setEditingSection] = useState<BestDealSection | null>(null);
  const [showRestoreConfirm, setShowRestoreConfirm] = useState(false);
  const [feedbackMsg, setFeedbackMsg] = useState('');

  const handleOpenAdd = () => {
    setEditingSection(null);
    setIsModalOpen(true);
  };

  const handleOpenEdit = (section: BestDealSection) => {
    setEditingSection(section);
    setIsModalOpen(true);
  };

  const handleSave = (sectionData: Omit<BestDealSection, 'id' | 'order'> | Partial<BestDealSection>) => {
    if (editingSection) {
      updateSection(editingSection.id, sectionData);
    } else {
      addSection(sectionData as Omit<BestDealSection, 'id' | 'order'>);
    }
  };

  const handleRestoreDefaults = () => {
    resetToDefault();
    setShowRestoreConfirm(false);
    setFeedbackMsg(
      'All 12 Best Deals showcase sections restored to defaults successfully!'
    );
    setTimeout(() => setFeedbackMsg(''), 4500);
  };

  const sortedSections = [...sections].sort((a, b) => (a.order || 0) - (b.order || 0));

  return (
    <div className="space-y-6">
      {/* Toast Feedback Notification */}
      {feedbackMsg && (
        <div className="p-3.5 bg-emerald-50 border border-emerald-200 text-emerald-900 rounded-xl text-xs font-bold flex items-center justify-between shadow-xs animate-in fade-in">
          <div className="flex items-center gap-2">
            <CheckCircle2 className="w-4 h-4 text-emerald-600 shrink-0" />
            <span>{feedbackMsg}</span>
          </div>
          <button
            type="button"
            onClick={() => setFeedbackMsg('')}
            className="text-emerald-700 hover:text-emerald-950 font-bold text-xs cursor-pointer p-1"
          >
            ✕
          </button>
        </div>
      )}

      {/* 1. Header Toolbar */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white p-5 rounded-2xl border border-zinc-200/90 shadow-2xs">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-primary/10 text-primary flex items-center justify-center font-bold">
              <Flame className="w-4 h-4" />
            </div>
            <h2 className="text-base sm:text-lg font-bold text-zinc-900">
              {'Best Deals Showcase Manager'}
            </h2>
          </div>
          <p className="text-xs text-zinc-500">
            {'Manage Category Showcases, Promo Banners, and product grids on the /best-deals page.'}
          </p>
        </div>

        <div className="flex items-center flex-wrap gap-2.5">
          <Link
            href="/best-deals"
            target="_blank"
            className="px-3.5 py-2 text-xs font-bold text-zinc-700 hover:text-zinc-950 bg-zinc-100 hover:bg-zinc-200/70 rounded-xl flex items-center gap-1.5 transition-colors"
          >
            <Eye className="w-3.5 h-3.5" />
            <span>{'View Live Page'}</span>
            <ExternalLink className="w-3 h-3 text-zinc-400" />
          </Link>

          {!showRestoreConfirm ? (
            <button
              type="button"
              onClick={() => setShowRestoreConfirm(true)}
              className="px-3.5 py-2 text-xs font-bold text-amber-700 hover:text-amber-800 bg-amber-50 hover:bg-amber-100/70 border border-amber-200/60 rounded-xl flex items-center gap-1.5 transition-colors cursor-pointer"
            >
              <RotateCcw className="w-3.5 h-3.5" />
              <span>{'Restore Defaults'}</span>
            </button>
          ) : (
            <div className="flex items-center gap-1.5 p-1.5 bg-amber-50 border border-amber-300 rounded-xl animate-in fade-in">
              <button
                type="button"
                onClick={handleRestoreDefaults}
                className="px-3 py-1.5 bg-amber-600 hover:bg-amber-700 text-white rounded-lg text-xs font-bold transition-colors cursor-pointer flex items-center gap-1 shadow-2xs"
              >
                <CheckCircle2 className="w-3.5 h-3.5" />
                <span>{'Confirm Restore'}</span>
              </button>
              <button
                type="button"
                onClick={() => setShowRestoreConfirm(false)}
                className="px-2.5 py-1.5 bg-white text-zinc-700 hover:bg-zinc-100 border border-zinc-200 rounded-lg text-xs font-bold transition-colors cursor-pointer"
              >
                ✕
              </button>
            </div>
          )}

          <button
            type="button"
            onClick={handleOpenAdd}
            className="px-4 py-2 text-xs font-bold text-white bg-primary hover:bg-primary-hover rounded-xl flex items-center gap-1.5 shadow-xs transition-all cursor-pointer"
          >
            <Plus className="w-4 h-4" />
            <span>{'Add Section'}</span>
          </button>
        </div>
      </div>

      {/* 2. Sections Table / Card List */}
      <div className="bg-white rounded-2xl border border-zinc-200/90 shadow-2xs overflow-hidden">
        <div className="px-5 py-3.5 border-b border-zinc-100 bg-zinc-50/60 flex items-center justify-between">
          <span className="text-xs font-bold text-zinc-700 uppercase tracking-wider">
            {`Total Sections: ${sortedSections.length}`}
          </span>
          <span className="text-2xs text-zinc-400">
            {'Click arrows to reorder layout'}
          </span>
        </div>

        <div className="divide-y divide-zinc-100">
          {sortedSections.map((section, index) => {
            const isFirst = index === 0;
            const isLast = index === sortedSections.length - 1;

            return (
              <div
                key={section.id}
                className="p-4 sm:p-5 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 hover:bg-zinc-50/50 transition-colors"
              >
                {/* Left Info & Banner Thumbnail */}
                <div className="flex items-center gap-3.5 flex-1 min-w-0">
                  {/* Order Badge & Reorder Buttons */}
                  <div className="flex flex-col items-center gap-1 shrink-0">
                    <button
                      type="button"
                      disabled={isFirst}
                      onClick={() => moveSection(section.id, 'up')}
                      className={`p-1 rounded-md transition-colors cursor-pointer ${
                        isFirst
                          ? 'text-zinc-300 cursor-not-allowed'
                          : 'text-zinc-600 hover:bg-zinc-200 hover:text-zinc-950'
                      }`}
                      title="Move Up"
                    >
                      <ArrowUp className="w-3.5 h-3.5" />
                    </button>
                    <span className="w-5 h-5 rounded-full bg-zinc-100 text-zinc-700 text-2xs font-black flex items-center justify-center border border-zinc-200">
                      {section.order}
                    </span>
                    <button
                      type="button"
                      disabled={isLast}
                      onClick={() => moveSection(section.id, 'down')}
                      className={`p-1 rounded-md transition-colors cursor-pointer ${
                        isLast
                          ? 'text-zinc-300 cursor-not-allowed'
                          : 'text-zinc-600 hover:bg-zinc-200 hover:text-zinc-950'
                      }`}
                      title="Move Down"
                    >
                      <ArrowDown className="w-3.5 h-3.5" />
                    </button>
                  </div>

                  {/* Banner Thumbnail Preview */}
                  <div className="relative w-16 h-20 rounded-lg overflow-hidden bg-zinc-900 border border-zinc-200 shrink-0">
                    {section.banner.image ? (
                      <Image
                        src={section.banner.image}
                        alt={section.titleEn || (section as any).title || "Best deal promotional section banner"}
                        fill
                        sizes="64px"
                        className="object-cover"
                        referrerPolicy="no-referrer"
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-zinc-500">
                        <Flame className="w-4 h-4" />
                      </div>
                    )}
                    <span className="absolute bottom-1 left-1 right-1 bg-black/70 text-white text-2xs font-bold text-center rounded-xs truncate px-0.5">
                      {(section.banner as any).badgeEn || (section.banner as any).tag || 'DEAL'}
                    </span>
                  </div>

                  {/* Text Details */}
                  <div className="space-y-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <h3 className="text-sm font-bold text-zinc-900">
                        {section.titleEn || (section as any).title}
                      </h3>
                      <span className="px-2 py-0.5 rounded-full bg-zinc-100 text-zinc-600 text-2xs font-semibold border border-zinc-200">
                        {section.categorySlug}
                      </span>
                    </div>

                    <div className="flex items-center gap-3 text-2xs text-zinc-500 flex-wrap">
                      <span>
                        Headline: <strong className="text-zinc-800">{(section.banner as any).headingEn || (section.banner as any).heading}</strong>
                      </span>
                      <span>•</span>
                      <span>
                        Badge: <strong className="text-primary">{(section.banner as any).badgeEn || (section.banner as any).tag}</strong>
                      </span>
                      <span>•</span>
                      <span>
                        Target: <span className="font-mono text-zinc-600">{section.seeMoreLink}</span>
                      </span>
                    </div>
                  </div>
                </div>

                {/* Right Actions */}
                <div className="flex items-center gap-2 self-end sm:self-center shrink-0">
                  {/* Status Toggle Button */}
                  <button
                    type="button"
                    onClick={() => toggleSection(section.id)}
                    className={`px-3 py-1.5 rounded-lg text-2xs font-bold flex items-center gap-1.5 transition-colors cursor-pointer ${
                      section.enabled
                        ? 'bg-emerald-50 text-emerald-700 border border-emerald-200 hover:bg-emerald-100'
                        : 'bg-zinc-100 text-zinc-500 border border-zinc-200 hover:bg-zinc-200'
                    }`}
                  >
                    {section.enabled ? (
                      <>
                        <CheckCircle2 className="w-3.5 h-3.5 text-emerald-600" />
                        <span>Active</span>
                      </>
                    ) : (
                      <>
                        <XCircle className="w-3.5 h-3.5 text-zinc-400" />
                        <span>Hidden</span>
                      </>
                    )}
                  </button>

                  {/* Edit Button */}
                  <button
                    type="button"
                    onClick={() => handleOpenEdit(section)}
                    className="p-2 text-zinc-600 hover:text-zinc-950 hover:bg-zinc-100 rounded-lg transition-colors cursor-pointer border border-zinc-200/80"
                    title="Edit Section"
                  >
                    <Edit3 className="w-3.5 h-3.5" />
                  </button>

                  {/* Delete Button */}
                  <button
                    type="button"
                    onClick={() => {
                      deleteSection(section.id);
                      setFeedbackMsg(
                        `Section "${section.titleEn || (section as any).title}" deleted`
                      );
                      setTimeout(() => setFeedbackMsg(''), 3500);
                    }}
                    className="p-2 text-red-600 hover:text-red-700 hover:bg-red-50 rounded-lg transition-colors cursor-pointer border border-red-200/60"
                    title="Delete Section"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              </div>
            );
          })}

          {sortedSections.length === 0 && (
            <div className="p-12 text-center space-y-3">
              <Flame className="w-8 h-8 text-zinc-300 mx-auto" />
              <p className="text-sm font-semibold text-zinc-600">
                No Best Deals sections configured yet.
              </p>
              <button
                type="button"
                onClick={resetToDefault}
                className="px-4 py-2 text-xs font-bold text-primary bg-primary/10 hover:bg-primary/20 rounded-xl"
              >
                Restore Default Sections
              </button>
            </div>
          )}
        </div>
      </div>

      {/* 3. Add / Edit Modal */}
      <BestDealSectionModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSave}
        initialData={editingSection}
      />
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import Image from 'next/image';
import { 
  Plus, 
  Upload, 
  Trash, 
  FolderPlus, 
  ChevronDown, 
  ChevronUp, 
  Pencil, 
  X, 
  Save,
  Layers,
  Image as ImageIcon,
  FolderTree,
  Tag,
  Check,
  RotateCcw,
  Loader2,
  AlertTriangle
} from 'lucide-react';
import { ResponsiveTableContainer } from '@/components/ui/ResponsiveTableContainer';
import { useCategoryStore, DEFAULT_CATEGORY_PLACEHOLDER, initialCategories } from '@/store/useCategoryStore';
import { SubCategoryItem } from '@/types';
import { ConfirmDialog } from '@/components/ui/ConfirmDialog';
import { useToastStore } from '@/store/useToastStore';

interface Category {
  id: string;
  name: string;
  image: string;
  subcategories?: (string | SubCategoryItem)[];
}

interface Product {
  id: string;
  category: string;
}

interface CategoriesTabProps {
  categories: Category[];
  newCatName: string;
  setNewCatName: (val: string) => void;
  newCatImage: string;
  setNewCatImage: (val: string) => void;
  handleAddCategory: (e: React.FormEvent) => void;
  handleImageUpload: (e: React.ChangeEvent<HTMLInputElement>, setter: (url: string) => void, folder: string) => void;
  products: Product[];
  deleteCategory: (catId: string) => void;
  updateCategory?: (id: string, updatedFields: { name: string; image: string; slug?: string; subcategories?: (string | SubCategoryItem)[] }) => void;
}

export const CategoriesTab: React.FC<CategoriesTabProps> = ({
  categories,
  newCatName,
  setNewCatName,
  newCatImage,
  setNewCatImage,
  handleAddCategory,
  handleImageUpload,
  products,
  deleteCategory,
  updateCategory: propUpdateCategory,
}) => {
  const { 
    addCategory,
    updateCategory: storeUpdateCategory,
    addSubcategory,
    deleteSubcategory,
    resetCategories
  } = useCategoryStore();
  const { addToast } = useToastStore();

  const [isImporting, setIsImporting] = useState(false);
  const [importStatus, setImportStatus] = useState<{ type: 'success' | 'error' | null; message: string }>({ type: null, message: '' });

  const [isConfirmLoading, setIsConfirmLoading] = useState(false);

  // Shared Confirmation Dialog State
  const [confirmDialog, setConfirmDialog] = useState<{
    open: boolean;
    title: string;
    message: string;
    confirmLabel?: string;
    cancelLabel?: string;
    onConfirm: () => void | Promise<void>;
  }>({
    open: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  const importDefaults = async () => {
    setIsImporting(true);
    setImportStatus({ type: null, message: '' });
    try {
      const { added, skipped } = await useCategoryStore.getState().importDefaultCategories();
      setImportStatus({ 
        type: 'success', 
        message: `Imported ${added} new, ${skipped} already existed.` 
      });
      setTimeout(() => setImportStatus({ type: null, message: '' }), 5000);
    } catch (err: any) {
      console.error('[ImportDefaults] Error:', err);
      setImportStatus({ 
        type: 'error', 
        message: 'Failed to import default categories.' 
      });
    } finally {
      setIsImporting(false);
    }
  };

  const [isAddCategoryOpenMobile, setIsAddCategoryOpenMobile] = useState(false);
  const [restoreSuccess, setRestoreSuccess] = useState(false);

  // Subcategory management state per category
  const [managingSubcatForId, setManagingSubcatForId] = useState<string | null>(null);
  const [newSubNameEn, setNewSubNameEn] = useState('');

  const handleRestoreDefaults = async () => {
    setIsConfirmLoading(true);
    try {
      await resetCategories();
      setRestoreSuccess(true);
      addToast('Categories restored to factory defaults!', 'success');
      setConfirmDialog(prev => ({ ...prev, open: false }));
      setTimeout(() => setRestoreSuccess(false), 3000);
    } catch (err) {
      addToast('Failed to restore categories', 'error');
    } finally {
      setIsConfirmLoading(false);
    }
  };

  const openRestoreConfirm = () => {
    setConfirmDialog({
      open: true,
      title: 'Restore Default Categories',
      message: 'Are you sure you want to reset all categories to defaults? This will wipe any custom categories and subcategories you created.',
      confirmLabel: 'Restore',
      cancelLabel: 'Cancel',
      onConfirm: handleRestoreDefaults,
    });
  };

  const openDeleteCategoryConfirm = (category: Category) => {
    setConfirmDialog({
      open: true,
      title: `Delete Category: ${category.name}`,
      message: `Are you sure you want to permanently delete the "${category.name}" category and all its nested subcategories?`,
      confirmLabel: 'Delete',
      cancelLabel: 'Cancel',
      onConfirm: async () => {
        setIsConfirmLoading(true);
        try {
          await deleteCategory(category.id);
          addToast(`Category "${category.name}" deleted successfully`, 'success');
          setConfirmDialog(prev => ({ ...prev, open: false }));
        } catch (err) {
          addToast('Failed to delete category', 'error');
        } finally {
          setIsConfirmLoading(false);
        }
      }
    });
  };

  const openDeleteSubcategoryConfirm = (catId: string, subId: string, subName: string) => {
    setConfirmDialog({
      open: true,
      title: `Remove Subcategory: ${subName}`,
      message: `Are you sure you want to remove the "${subName}" subcategory?`,
      confirmLabel: 'Delete',
      cancelLabel: 'Cancel',
      onConfirm: async () => {
        setIsConfirmLoading(true);
        try {
          await deleteSubcategory(catId, subId);
          addToast(`Subcategory "${subName}" removed`, 'success');
          setConfirmDialog(prev => ({ ...prev, open: false }));
        } catch (err) {
          addToast('Failed to remove subcategory', 'error');
        } finally {
          setIsConfirmLoading(false);
        }
      }
    });
  };
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);
  const [editName, setEditName] = useState('');
  const [editImage, setEditImage] = useState('');
  const [editSubcategories, setEditSubcategories] = useState<(string | SubCategoryItem)[]>([]);
  const [isSavingEdit, setIsSavingEdit] = useState(false);

  const handleOpenEdit = (category: Category) => {
    setEditingCategory(category);
    setEditName(category.name);
    setEditImage(category.image);
    setEditSubcategories(category.subcategories ? [...category.subcategories] : []);
  };

  const handleCloseEdit = () => {
    setEditingCategory(null);
    setEditName('');
    setEditImage('');
    setEditSubcategories([]);
    setIsSavingEdit(false);
  };

  const handleSaveEdit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCategory || !editName.trim()) return;

    setIsSavingEdit(true);
    const updatedData = {
      name: editName.trim(),
      image: editImage.trim() || editingCategory.image || DEFAULT_CATEGORY_PLACEHOLDER,
      slug: editName.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-'),
      subcategories: editSubcategories,
    };

    if (propUpdateCategory) {
      propUpdateCategory(editingCategory.id, updatedData);
    } else {
      storeUpdateCategory(editingCategory.id, updatedData);
    }

    setIsSavingEdit(false);
    handleCloseEdit();
  };

  const handleAddSubcategoryDirect = (catId: string, e: React.FormEvent) => {
    e.preventDefault();
    if (!newSubNameEn.trim()) return;
    addSubcategory(catId, {
      name: newSubNameEn.trim(),
    });
    setNewSubNameEn('');
  };

  const getSubName = (sub: string | SubCategoryItem) => {
    if (typeof sub === 'string') return sub;
    return sub.name;
  };

  const getSubId = (sub: string | SubCategoryItem) => {
    if (typeof sub === 'string') return sub;
    return sub.id;
  };

  return (
    <div className="space-y-3">
      {/* Top Banner explaining Nested Category System */}
      <div className="bg-blue-50/70 border border-blue-200 rounded-xl p-3 flex items-center justify-between flex-wrap gap-2 text-xs">
        <div className="flex items-center gap-2 text-blue-900">
          <FolderTree className="w-4 h-4 text-blue-600 shrink-0" />
          <span className="font-semibold">
            {'Nested Category & Subcategory Hierarchy Active. You can manage subcategories for any parent category below.'}
          </span>
        </div>

        <div className="flex items-center gap-2">
          {isImporting ? (
            <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-lg bg-blue-50 text-blue-700 border border-blue-200 text-2xs font-bold shadow-2xs">
              <Loader2 className="w-3 h-3 animate-spin" />
              <span>{'Importing...'}</span>
            </span>
          ) : (
            <button
              type="button"
              onClick={importDefaults}
              className="px-2.5 py-1 bg-white hover:bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-lg text-2xs font-bold flex items-center gap-1 cursor-pointer transition-colors shadow-2xs"
            >
              <Plus className="w-3 h-3" />
              <span>{'Import Defaults'}</span>
            </button>
          )}

          {importStatus.type && (
            <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-lg border text-2xs font-bold animate-in fade-in ${
              importStatus.type === 'success' 
                ? 'bg-emerald-50 text-emerald-700 border-emerald-200' 
                : 'bg-red-50 text-red-700 border-red-200'
            }`}>
              {importStatus.type === 'success' ? <Check className="w-3 h-3" /> : <X className="w-3 h-3" />}
              <span>{importStatus.message}</span>
            </span>
          )}

          {restoreSuccess && (
            <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg bg-emerald-100 text-emerald-800 border border-emerald-300 text-2xs font-bold animate-in fade-in">
              <Check className="w-3 h-3 text-emerald-600 stroke-[3]" />
              <span>{'Defaults Restored!'}</span>
            </span>
          )}

          <button
            type="button"
            onClick={openRestoreConfirm}
            className="px-2.5 py-1 bg-white hover:bg-blue-100 text-blue-700 border border-blue-200 rounded-lg text-2xs font-bold flex items-center gap-1 cursor-pointer transition-colors shadow-2xs"
          >
            <RotateCcw className="w-3 h-3" />
            <span>{'Restore Defaults'}</span>
          </button>
        </div>
      </div>

      {/* CREATE NEW PARENT CATEGORY CARD */}
      <div className="bg-white rounded-xl border border-neutral-200 p-3.5 shadow-2xs">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <FolderPlus className="w-4 h-4 text-primary" />
            <h3 className="font-sans text-xs sm:text-sm font-bold text-neutral-900">
              {'Create New Parent Category'}
            </h3>
          </div>
          {/* Mobile Collapse/Expand Toggle */}
          <button
            type="button"
            onClick={() => setIsAddCategoryOpenMobile(!isAddCategoryOpenMobile)}
            className="sm:hidden px-2.5 py-1 rounded-lg bg-neutral-100 hover:bg-neutral-200 border border-neutral-200 text-xs font-bold text-neutral-700 flex items-center gap-1 cursor-pointer transition-colors"
          >
            {isAddCategoryOpenMobile ? (
              <>
                <span>{'Collapse'}</span>
                <ChevronUp className="w-3.5 h-3.5" />
              </>
            ) : (
              <>
                <Plus className="w-3.5 h-3.5 text-primary" />
                <span>{'Add Category'}</span>
                <ChevronDown className="w-3.5 h-3.5" />
              </>
            )}
          </button>
        </div>

        <div className={`${isAddCategoryOpenMobile ? 'block' : 'hidden sm:block'} mt-2.5`}>
          <form 
            onSubmit={(e) => {
              handleAddCategory(e);
              setNewCatName('');
              setNewCatImage('');
            }} 
