                  </div>
                </div>

                {sec.enabled && (
                  <div className="mt-2.5 pt-2.5 border-t border-zinc-100 grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs">
                    <div>
                      <label className="text-xs font-semibold text-text-muted block mb-1">Custom Title</label>
