                        )}
                        <span className="text-xs font-black uppercase text-text-main">{log.channel}</span>
                      </div>
                    </td>

                    <td className="px-3 py-2 border-b border-r border-border-color whitespace-nowrap">
                      <span className="font-mono font-bold text-text-main">{log.recipient}</span>
                    </td>

                    <td className="px-3 py-2 border-b border-r border-border-color whitespace-nowrap">
                      <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-2xs font-black uppercase ${
                        log.status === 'sent'
                          ? 'bg-emerald-50 text-emerald-700 border border-emerald-200'
                          : log.status === 'failed'
                          ? 'bg-rose-50 text-rose-700 border border-rose-200'
                          : 'bg-surface-subtle text-text-muted border border-border-color'
                      }`}>
                        <div className={`w-1.5 h-1.5 rounded-full ${
                          log.status === 'sent' ? 'bg-emerald-500' : log.status === 'failed' ? 'bg-rose-500' : 'bg-zinc-400'
                        }`} />
                        <span>{log.status}</span>
                      </div>
                    </td>

                    <td className="px-3 py-2 border-b border-r border-border-color max-w-sm">
                      <p className="font-bold text-text-main leading-snug truncate">{log.summary}</p>
                      {log.details && (
                        <p className="text-2xs text-text-muted font-mono mt-0.5 truncate">{log.details}</p>
                      )}
                    </td>

                    <td className="px-3 py-2 border-b border-r border-border-color text-right whitespace-nowrap">
                      <button
                        type="button"
                        onClick={() => setSelectedLog(log)}
                        className="px-3 py-1 bg-surface-subtle hover:bg-zinc-200 text-text-muted text-xs font-bold transition-colors cursor-pointer rounded border border-border-color"
                      >
                        {'Inspect'}
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </ResponsiveTableContainer>
      </div>

      {/* Log Details Modal */}
      {selectedLog && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-xs flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl max-w-lg w-full p-6 space-y-5 shadow-2xl border border-border-color animate-scale-in">
            <div className="flex items-center justify-between border-b border-zinc-100 pb-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-surface-dark text-white flex items-center justify-center">
                  <Activity className="w-5 h-5 text-primary" />
                </div>
                <div>
                  <h3 className="text-base font-black text-zinc-950">
                    {'Log Audit Details'}
                  </h3>
                  <p className="text-xs text-text-subtle font-mono">{selectedLog.id}</p>
                </div>
              </div>
              <button
                onClick={() => setSelectedLog(null)}
                className="p-1.5 rounded-xl text-text-subtle hover:text-text-main hover:bg-surface-subtle"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="space-y-3 text-xs">
              <div className="grid grid-cols-2 gap-3 bg-surface-subtle p-4 rounded-2xl border border-zinc-100">
                <div>
                  <span className="text-2xs font-bold text-text-subtle uppercase block">{'Channel'}</span>
                  <span className="font-black text-text-main uppercase">{selectedLog.channel}</span>
                </div>
                <div>
                  <span className="text-2xs font-bold text-text-subtle uppercase block">{'Status'}</span>
                  <span className={`font-black uppercase ${selectedLog.status === 'sent' ? 'text-emerald-600' : 'text-rose-600'}`}>
                    {selectedLog.status}
                  </span>
                </div>
                <div>
                  <span className="text-2xs font-bold text-text-subtle uppercase block">{'Recipient'}</span>
                  <span className="font-mono font-bold text-text-main">{selectedLog.recipient}</span>
                </div>
                <div>
                  <span className="text-2xs font-bold text-text-subtle uppercase block">{'Gateway Provider'}</span>
                  <span className="font-bold text-text-main">{selectedLog.provider || 'Default'}</span>
                </div>
              </div>

              <div className="space-y-1.5">
                <span className="text-2xs font-bold text-text-subtle uppercase block">{'Summary'}</span>
                <div className="p-3 bg-surface-subtle rounded-xl text-text-main font-medium">
                  {selectedLog.summary}
                </div>
              </div>

              {selectedLog.details && (
                <div className="space-y-1.5">
                  <span className="text-2xs font-bold text-text-subtle uppercase block">{'Payload & Response'}</span>
                  <pre className="p-3 bg-surface-dark text-white rounded-xl font-mono text-xs overflow-x-auto">
                    {selectedLog.details}
                  </pre>
                </div>
              )}
            </div>

            <div className="pt-2 flex justify-end">
              <button
                onClick={() => setSelectedLog(null)}
                className="px-5 py-2.5 rounded-xl bg-zinc-950 text-white text-xs font-bold uppercase tracking-wider hover:bg-zinc-800 transition-colors"
              >
                {'Close'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Floating Toast */}
      {toastMsg && (
        <div className="fixed bottom-6 right-6 z-50 bg-zinc-950 text-white px-6 py-4 rounded-2xl shadow-2xl border border-border-dark flex items-center gap-3 animate-slide-up">
          <Zap className="w-5 h-5 text-primary" />
          <span className="text-xs font-bold">{toastMsg}</span>
        </div>
      )}
    </div>
  );
}

export { NotificationsTab as ServiceMonitoringTab };

'use client';

import React, { useState } from 'react';
import Image from 'next/image';
import { Package, Search, Eye, FileText, Trash2, Download, CheckCircle2, Phone, MapPin, User as UserIcon, MessageCircle, AlertTriangle } from 'lucide-react';
import { Order, useOrderStore } from '@/store/useOrderStore';
import { useProductStore } from '@/store/useProductStore';
import { Product } from '@/types';
import { ResponsiveTableContainer } from '@/components/ui/ResponsiveTableContainer';
import { CustomDropdown } from '@/components/ui/CustomDropdown';
import { exportOrdersToCSV, exportOrdersToJSON } from '@/lib/dataTransferUtils';
import { cleanWhatsAppNumber } from '@/lib/utils';
import { InvoiceModal } from '@/components/invoice/InvoiceModal';
import { AdminProductDetailsModal } from '@/components/admin/modals/AdminProductDetailsModal';
import { ConfirmDialog } from '@/components/ui/ConfirmDialog';
import { useToastStore } from '@/store/useToastStore';

interface OrdersTabProps {
  orders: Order[];
  adminOrderSearch: string;
  setAdminOrderSearch: (val: string) => void;
  adminOrderStatusFilter: string;
  setAdminOrderStatusFilter: (status: any) => void;

  formatBDT: (amount: number) => string;
  updateOrderStatus: (orderId: string, status: any) => void;
  setSelectedOrderDetails: (order: Order) => void;
  deleteOrder: (orderId: string) => void;
}

export const OrdersTab: React.FC<OrdersTabProps> = ({
  orders,
  adminOrderSearch,
  setAdminOrderSearch,
  adminOrderStatusFilter,
  setAdminOrderStatusFilter,
    formatBDT,
  updateOrderStatus,
  setSelectedOrderDetails,
  deleteOrder,
}) => {
  const { clearAllOrders } = useOrderStore();
  const { products } = useProductStore();
  const { addToast } = useToastStore();
  const [selectedOrderIds, setSelectedOrderIds] = useState<string[]>([]);
  const [selectedInvoiceOrder, setSelectedInvoiceOrder] = useState<Order | null>(null);
  const [selectedProductDetails, setSelectedProductDetails] = useState<Product | null>(null);
  const [selectedOrderItemContext, setSelectedOrderItemContext] = useState<any>(null);
  const [isConfirmLoading, setIsConfirmLoading] = useState(false);

  // Shared Confirmation Dialog State
  const [confirmDialog, setConfirmDialog] = useState<{
    open: boolean;
    title: string;
    message: string;
    confirmLabel?: string;
    cancelLabel?: string;
    onConfirm: () => void | Promise<void>;
  }>({
    open: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  const handleOpenProductDetails = (item: any) => {
    const prodId = item.product?.id || (item as any)?.productId;
    const catalogProd = products.find((p) => p.id === prodId) || item.product;
    if (!catalogProd) return;
    setSelectedProductDetails(catalogProd);
    setSelectedOrderItemContext({
      selectedSize: item.selectedSize || (item as any)?.size,
      selectedColor: item.selectedColor,
      quantity: item.quantity,
      customPrice: item.customPrice,
    });
  };

  const handleWipeOrders = async () => {
    setIsConfirmLoading(true);
    try {
      await clearAllOrders();
      setSelectedOrderIds([]);
      setConfirmDialog(prev => ({ ...prev, open: false }));
      addToast('All order data reset and wiped successfully!', 'success');
    } catch (err: any) {
      addToast(err?.message || 'Failed to wipe orders', 'error');
    } finally {
      setIsConfirmLoading(false);
    }
  };

  const openWipeConfirm = () => {
    setConfirmDialog({
      open: true,
      title: 'Wipe All Order Data',
      message: 'Are you sure you want to permanently delete ALL orders from the database? This action is destructive and cannot be undone.',
      confirmLabel: 'Reset',
      cancelLabel: 'Cancel',
      onConfirm: handleWipeOrders,
    });
  };

  const openBulkDeleteConfirm = () => {
    setConfirmDialog({
      open: true,
      title: `Delete ${selectedOrderIds.length} Orders`,
      message: `Are you sure you want to permanently delete these ${selectedOrderIds.length} selected orders?`,
      confirmLabel: 'Delete',
      cancelLabel: 'Cancel',
      onConfirm: async () => {
        setIsConfirmLoading(true);
        try {
          await Promise.all(selectedOrderIds.map(id => deleteOrder(id)));
          addToast(`${selectedOrderIds.length} orders deleted successfully`, 'success');
          setSelectedOrderIds([]);
          setConfirmDialog(prev => ({ ...prev, open: false }));
        } catch (err: any) {
          addToast('Failed to delete some orders', 'error');
        } finally {
          setIsConfirmLoading(false);
        }
      }
    });
  };

  const openSingleDeleteConfirm = (order: Order) => {
    setConfirmDialog({
      open: true,
      title: `Delete Order #${order.id}`,
      message: `Are you sure you want to permanently delete this order for ${order.userName}?`,
      confirmLabel: 'Delete',
      cancelLabel: 'Cancel',
      onConfirm: async () => {
        setIsConfirmLoading(true);
        try {
          await deleteOrder(order.id);
          addToast(`Order #${order.id} deleted successfully`, 'success');
          setConfirmDialog(prev => ({ ...prev, open: false }));
        } catch (err: any) {
          addToast('Failed to delete order', 'error');
        } finally {
          setIsConfirmLoading(false);
        }
      }
    });
  };

  const pendingCount = orders.filter((o) => o.status === 'Pending').length;
  const processingCount = orders.filter((o) => o.status === 'Processing').length;
  const shippedCount = orders.filter((o) => o.status === 'Shipped' || (o as any).status === 'Dispatched').length;
  const deliveredCount = orders.filter((o) => o.status === 'Delivered').length;
  const cancelledCount = orders.filter((o) => o.status === 'Cancelled').length;

  const filteredAdminOrders = orders.filter((o) => {
    const query = adminOrderSearch.toLowerCase().trim();
    const matchesSearch = !query || 
      o.id.toLowerCase().includes(query) ||
      o.userName.toLowerCase().includes(query) ||
      (o.userEmail && o.userEmail.toLowerCase().includes(query)) ||
      (o.phone && o.phone.includes(query)) ||
      (o.address && o.address.toLowerCase().includes(query));
    const matchesStatus = adminOrderStatusFilter === 'All' || o.status === adminOrderStatusFilter;
    return matchesSearch && matchesStatus;
  });

  const toggleSelectAll = () => {
    if (selectedOrderIds.length === filteredAdminOrders.length) {
      setSelectedOrderIds([]);
    } else {
      setSelectedOrderIds(filteredAdminOrders.map((o) => o.id));
    }
  };

  const toggleSelectOrder = (id: string) => {
    if (selectedOrderIds.includes(id)) {
      setSelectedOrderIds(selectedOrderIds.filter((i) => i !== id));
    } else {
      setSelectedOrderIds([...selectedOrderIds, id]);
    }
  };

  const handleBulkStatusUpdate = (status: any) => {
    if (selectedOrderIds.length === 0) return;
    selectedOrderIds.forEach((id) => {
      updateOrderStatus(id, status);
    });
    addToast(`Successfully updated ${selectedOrderIds.length} orders to status: ${status}`, 'success');
    setSelectedOrderIds([]);
  };

  return (
    <div className="space-y-2">
      {/* Header, Status Metric Pills & Search Bar - Compact Control Bar */}
      <div className="bg-white rounded-2xl border border-zinc-200 p-3.5 sm:p-4 shadow-sm space-y-3 font-sans">
        {/* Top Row: Title + Total Orders Badge + Compact Search Input */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
          <div className="flex items-center gap-2.5">
            <div className="p-2.5 rounded-2xl bg-primary/10 text-primary shrink-0">
              <Package className="w-5 h-5 sm:w-6 sm:h-6" />
            </div>
            <div>
              <h2 className="font-sans text-base sm:text-lg font-black text-zinc-950 flex items-center gap-2">
                <span>{'Orders Fulfillment & Dispatch Queue'}</span>
              </h2>
              <p className="text-xs text-zinc-600 font-semibold mt-0.5">
                {'Manage customer orders, addresses & fulfillment status'}
              </p>
            </div>
            <span className="text-xs font-black bg-primary text-white px-3 py-1 rounded-full ml-auto sm:ml-2 shadow-2xs whitespace-nowrap shrink-0 inline-flex items-center gap-1">
              <span>{orders.length}</span>
              <span>{'Total'}</span>
            </span>
          </div>

          <div className="flex items-center gap-1.5 w-full sm:w-auto flex-wrap">
            <div className="relative flex-1 sm:w-60">
              <Search className="w-3.5 h-3.5 text-zinc-400 absolute left-2.5 top-1/2 -translate-y-1/2" />
              <input
                type="text"
                value={adminOrderSearch}
                onChange={(e) => setAdminOrderSearch(e.target.value)}
                placeholder={'Search Order ID, customer, phone...'}
                className="w-full h-8 pl-8 pr-2.5 text-xs bg-zinc-50 border border-zinc-200 rounded-xl focus:bg-white focus:outline-hidden focus:border-primary text-zinc-900 font-sans"
              />
            </div>
            {adminOrderSearch && (
              <button
                type="button"
                onClick={() => setAdminOrderSearch('')}
                className="px-2 h-8 rounded-xl border border-zinc-200 text-xs font-bold text-zinc-500 hover:bg-zinc-100 cursor-pointer"
              >
                Clear
              </button>
            )}

            <button
              type="button"
              onClick={() => exportOrdersToCSV(filteredAdminOrders)}
              className="h-8 px-2.5 rounded-xl border border-zinc-200 bg-white hover:bg-zinc-50 text-zinc-700 text-xs font-bold flex items-center gap-1 shadow-2xs cursor-pointer active:scale-95"
              title="Export Orders as CSV"
            >
              <Download className="w-3.5 h-3.5 text-emerald-600" />
              <span>CSV</span>
            </button>

            <button
              type="button"
              onClick={() => exportOrdersToJSON(filteredAdminOrders)}
              className="h-8 px-2.5 rounded-xl border border-zinc-200 bg-white hover:bg-zinc-50 text-zinc-700 text-xs font-bold flex items-center gap-1 shadow-2xs cursor-pointer active:scale-95"
              title="Export Orders as JSON"
            >
              <Download className="w-3.5 h-3.5 text-blue-600" />
              <span>JSON</span>
            </button>

            {orders.length > 0 && (
              <button
                type="button"
                onClick={openWipeConfirm}
                className="h-8 px-2.5 rounded-xl border border-red-200 bg-red-50 hover:bg-red-100 text-red-700 text-xs font-bold flex items-center gap-1 shadow-2xs cursor-pointer active:scale-95"
                title="Reset / Wipe all orders for clean production launch"
              >
                <Trash2 className="w-3.5 h-3.5 text-red-600" />
                <span>{'Reset'}</span>
              </button>
            )}
          </div>
        </div>

        {/* Status Metric Pills */}
        <div className="grid grid-cols-3 sm:grid-cols-6 gap-1.5 pt-1">
          {[
            { key: 'All', label: 'All Orders', count: orders.length },
            { key: 'Pending', label: 'Pending', count: pendingCount },
            { key: 'Processing', label: 'Processing', count: processingCount },
            { key: 'Shipped', label: 'Shipped', count: shippedCount },
            { key: 'Delivered', label: 'Delivered', count: deliveredCount },
            { key: 'Cancelled', label: 'Cancelled', count: cancelledCount },
          ].map((pill) => (
            <button
              key={pill.key}
              type="button"
              onClick={() => setAdminOrderStatusFilter(pill.key as any)}
              className={`p-1.5 rounded-xl border text-center transition-all cursor-pointer font-sans ${
                adminOrderStatusFilter === pill.key
                  ? 'bg-secondary text-white font-bold border-secondary shadow-2xs'
                  : 'bg-zinc-50 hover:bg-zinc-100 text-zinc-700 border-zinc-200'
              }`}
            >
              <div className="text-2xs font-bold uppercase tracking-wider truncate">{pill.label}</div>
              <div className="text-xs font-black mt-0.5">{pill.count}</div>
            </button>
          ))}
        </div>

        {/* Bulk Actions Bar */}
        {selectedOrderIds.length > 0 && (
          <div className="flex items-center justify-between gap-2 p-2 bg-amber-50 border border-amber-200 rounded-xl text-xs font-sans">
            <span className="font-bold text-amber-900">
              {selectedOrderIds.length} {'orders selected'}
            </span>
            <div className="flex items-center gap-1.5 flex-wrap">
              <button
                type="button"
                onClick={() => handleBulkStatusUpdate('Processing')}
                className="px-2.5 py-1 bg-blue-600 text-white rounded-lg font-bold text-2xs hover:bg-blue-700 transition-colors cursor-pointer"
              >
                Set Processing
              </button>
              <button
                type="button"
                onClick={() => handleBulkStatusUpdate('Shipped')}
                className="px-2.5 py-1 bg-purple-600 text-white rounded-lg font-bold text-2xs hover:bg-purple-700 transition-colors cursor-pointer"
              >
                Set Shipped
              </button>
              <button
                type="button"
                onClick={() => handleBulkStatusUpdate('Delivered')}
                className="px-2.5 py-1 bg-emerald-600 text-white rounded-lg font-bold text-2xs hover:bg-emerald-700 transition-colors cursor-pointer"
              >
                Set Delivered
              </button>
              <button
                type="button"
                onClick={openBulkDeleteConfirm}
                className="px-2.5 py-1 bg-red-600 text-white rounded-lg font-bold text-2xs hover:bg-red-700 transition-colors cursor-pointer"
              >
                {'Delete'}
              </button>
              <button
                type="button"
                onClick={() => setSelectedOrderIds([])}
                className="px-2.5 py-1 bg-zinc-200 text-zinc-700 rounded-lg font-bold text-2xs hover:bg-zinc-300 transition-colors cursor-pointer"
              >
                Deselect
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Orders Table */}
      <ResponsiveTableContainer showScrollCues={true}>
        <table className="w-full text-left text-xs font-sans whitespace-nowrap border-collapse min-w-[950px]">
          <thead className="bg-zinc-100 text-zinc-700 uppercase tracking-wider text-xs font-bold sticky top-0 z-10 shadow-[0_1px_2px_rgba(0,0,0,0.05)]">
            <tr>
              <th className="px-2.5 py-2.5 border-b border-r border-zinc-200 bg-zinc-100 w-10 text-center">
                <input
                  type="checkbox"
                  checked={filteredAdminOrders.length > 0 && selectedOrderIds.length === filteredAdminOrders.length}
                  onChange={toggleSelectAll}
                  className="rounded border-zinc-300 text-primary focus:ring-primary cursor-pointer"
                />
              </th>
              <th className="px-3 py-2.5 border-b border-r border-zinc-200 bg-zinc-100">Order ID</th>
              <th className="px-3.5 py-2.5 border-b border-r border-zinc-200 bg-zinc-100">Customer & Contact</th>
              <th className="px-3 py-2.5 border-b border-r border-zinc-200 bg-zinc-100">Date</th>
              <th className="px-3.5 py-2.5 border-b border-r border-zinc-200 bg-zinc-100">Items Summary</th>
              <th className="px-3 py-2.5 border-b border-r border-zinc-200 bg-zinc-100 text-right">Total (BDT)</th>
              <th className="px-3 py-2.5 border-b border-r border-zinc-200 bg-zinc-100 text-center">Status Control</th>
              <th className="px-3 py-2.5 border-b border-r border-zinc-200 bg-zinc-100 text-center">Actions</th>
            </tr>
          </thead>
          <tbody className="bg-white">
            {filteredAdminOrders.length === 0 ? (
              <tr>
                <td colSpan={8} className="text-center py-10 border-b border-r border-zinc-200 text-zinc-400 font-bold text-xs uppercase tracking-wider">
                  {'No orders found matching filter criteria.'}
                </td>
              </tr>
            ) : (
              filteredAdminOrders.map((order) => {
                const isSelected = selectedOrderIds.includes(order.id);

                return (
                  <tr key={order.id} className={`hover:bg-amber-50/40 transition-colors group ${isSelected ? 'bg-amber-50/60' : ''}`}>
                    <td className="px-2.5 py-2 border-b border-r border-zinc-200 text-center">
                      <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={() => toggleSelectOrder(order.id)}
                        className="rounded border-zinc-300 text-primary focus:ring-primary cursor-pointer"
                      />
                    </td>

                    {/* Order ID - Clickable to open details */}
                    <td className="px-3 py-2 border-b border-r border-zinc-200 font-bold font-mono text-zinc-900 whitespace-nowrap text-xs">
                      <button
                        type="button"
                        onClick={() => setSelectedOrderDetails(order)}
                        className="text-primary hover:underline flex items-center gap-1 font-extrabold cursor-pointer"
                        title="Click to view full order details"
                      >
                        <span>#{order.id}</span>
                      </button>
                    </td>

                    {/* Clean Customer Details */}
                    <td className="px-3.5 py-2 border-b border-r border-zinc-200 min-w-[170px]">
                      <div className="font-extrabold text-xs text-zinc-900 flex items-center gap-1.5">
                        <UserIcon className="w-3.5 h-3.5 text-primary shrink-0" />
                        <span className="truncate max-w-[130px]">{order.userName}</span>
                      </div>
                      <div className="text-xs text-zinc-700 font-mono font-semibold flex items-center gap-1.5 mt-1">
                        <Phone className="w-3 h-3 text-zinc-500 shrink-0" />
                        <span>{order.phone || 'N/A'}</span>
                        {order.phone && (
                          <div className="flex items-center gap-1 ml-auto">
                            <a
                              href={`tel:${order.phone.replace(/[^\d+]/g, '')}`}
                              className="p-1 rounded-md bg-zinc-100 hover:bg-zinc-200 text-zinc-700 transition-colors"
                              title="Call customer directly"
                            >
                              <Phone className="w-2.5 h-2.5" />
                            </a>
                            <a
                              href={`https://wa.me/${cleanWhatsAppNumber(order.phone)}?text=${encodeURIComponent(
                                `Hello ${order.userName}, we are contacting you from MAGMATI regarding your order #${order.id}.`
                              )}`}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="p-1 rounded-md bg-emerald-50 hover:bg-emerald-100 text-emerald-700 border border-emerald-200 transition-colors"
                              title="Message customer on WhatsApp"
                            >
                              <MessageCircle className="w-2.5 h-2.5" />
                            </a>
                          </div>
                        )}
                      </div>
                      {order.district && (
                        <div className="mt-1">
                          <span className="inline-block bg-zinc-100 text-zinc-700 text-2xs font-extrabold px-1.5 py-0.2 rounded border border-zinc-200">
                            📍 {order.district}
                          </span>
                        </div>
                      )}
                    </td>

                    <td className="px-3 py-2 border-b border-r border-zinc-200 text-zinc-600 font-medium whitespace-nowrap text-2xs">
                      {order.date}
                    </td>

                    {/* Items summary with Catalog Thumbnails and Click-to-View Product Details */}
                    <td className="px-3.5 py-2.5 border-b border-r border-zinc-200 min-w-[240px]">
                      <div className="space-y-1.5">
                        {order.items.map((it, idx) => {
                          const prodId = it.product?.id || (it as any)?.productId;
                          const catalogProd = products.find((p) => p.id === prodId) || it.product;
                          const prodName = catalogProd?.name || it.product?.name || (it as any)?.name || 'Product';
                          const prodImg = catalogProd?.images?.[0] || catalogProd?.image || it.product?.image || it.product?.images?.[0];
                          const sizeLabel = it.selectedSize || (it as any)?.size || 'Standard';
                          const qty = it.quantity || 1;

                          return (
                            <div 
                              key={idx} 
                              className="flex items-center gap-2 group/item"
                            >
                              {/* Product Thumbnail - Clickable */}
                              <button
                                type="button"
                                onClick={() => handleOpenProductDetails(it)}
                                className="relative w-8 h-8 rounded-lg overflow-hidden border border-zinc-200 bg-zinc-100 shrink-0 hover:ring-2 hover:ring-primary/40 transition-all cursor-pointer shadow-2xs group-hover/item:scale-105 active:scale-95"
                                title={`Click to view full details of "${prodName}"`}
                              >
                                {prodImg ? (
                                  <Image
                                    src={prodImg}
                                    alt={prodName}
                                    fill
                                    className="object-cover"
                                    referrerPolicy="no-referrer"
                                    sizes="32px"
                                  />
                                ) : (
                                  <div className="w-full h-full flex items-center justify-center bg-zinc-100 text-zinc-400">
                                    <Package className="w-3.5 h-3.5" />
                                  </div>
                                )}
                              </button>

                              {/* Product Name & Variations - Clickable */}
                              <div className="min-w-0 flex-1">
                                <button
                                  type="button"
                                  onClick={() => handleOpenProductDetails(it)}
                                  className="text-left font-semibold text-xs text-zinc-900 hover:text-primary hover:underline transition-colors truncate block max-w-[180px] cursor-pointer"
                                  title={`Click to view details for "${prodName}"`}
                                >
                                  {prodName}
                                </button>
                                <div className="flex items-center gap-1.5 text-2xs text-zinc-500 font-mono">
                                  <span className="bg-zinc-100 px-1 rounded text-zinc-700 font-semibold border border-zinc-200">
                                    {sizeLabel}
                                  </span>
                                  <span>×</span>
                                  <span className="font-bold text-zinc-900">{qty}</span>
                                </div>
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </td>

                    <td className="px-3 py-2 border-b border-r border-zinc-200 font-bold text-right text-zinc-900 whitespace-nowrap text-xs">
                      {formatBDT(order.total)}
                    </td>

                    <td className="px-3 py-2 border-b border-r border-zinc-200 text-center min-w-[120px]">
                      <CustomDropdown
                        value={order.status}
                        onChange={(val) => updateOrderStatus(order.id, val as Order['status'])}
                        searchable={false}
                        options={[
                          { value: 'Pending', label: 'Pending' },
                          { value: 'Processing', label: 'Processing' },
                          { value: 'Shipped', label: 'Shipped' },
                          { value: 'Delivered', label: 'Delivered' },
                          { value: 'Cancelled', label: 'Cancelled' },
                        ]}
                        triggerClassName="h-7 px-2 text-2xs font-bold rounded-lg bg-zinc-50 border-zinc-200"
                        dropdownClassName="min-w-[120px]"
                      />
                    </td>

                    {/* Actions Column: View Details, Printable Invoice, Delete */}
                    <td className="px-3 py-2 border-b border-r border-zinc-200 text-center">
                      <div className="flex items-center justify-center gap-1.5">
                        <button
                          type="button"
                          onClick={() => setSelectedOrderDetails(order)}
                          className="px-2 py-1 bg-primary text-white hover:bg-primary-hover rounded-lg text-2xs font-bold transition-all inline-flex items-center gap-1 cursor-pointer shadow-2xs active:scale-95"
                          title="View Full Customer & Shipping Details"
                        >
                          <Eye className="w-3 h-3" />
                          <span>{'Details'}</span>
                        </button>

                        <button
                          type="button"
                          onClick={() => setSelectedInvoiceOrder(order)}
                          className="px-2 py-1 bg-zinc-100 hover:bg-zinc-200 text-zinc-800 border border-zinc-300 rounded-lg text-2xs font-bold transition-colors inline-flex items-center gap-1 cursor-pointer"
                          title="View Official Tax Invoice"
                        >
                          <FileText className="w-3 h-3 text-zinc-600" />
                          <span>Invoice</span>
                        </button>

                        <button
                          type="button"
                          onClick={() => openSingleDeleteConfirm(order)}
                          className="px-1.5 py-1 bg-rose-50 hover:bg-rose-100 text-rose-600 border border-rose-200 rounded-lg text-2xs font-bold transition-colors inline-flex items-center gap-0.5 cursor-pointer"
                          title="Delete Order"
                        >
                          <Trash2 className="w-3 h-3" />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </ResponsiveTableContainer>

      {/* Official Tax Invoice Modal for Admin */}
      <InvoiceModal
        order={selectedInvoiceOrder}
        isOpen={!!selectedInvoiceOrder}
        onClose={() => setSelectedInvoiceOrder(null)}
      />

      {/* Product Details Modal for Ordered Items */}
      <AdminProductDetailsModal
        isOpen={!!selectedProductDetails}
        product={selectedProductDetails}
        orderItemContext={selectedOrderItemContext}
        onClose={() => {
          setSelectedProductDetails(null);
          setSelectedOrderItemContext(null);
        }}
        formatBDT={formatBDT}
      />

      {/* Shared Delete Confirmation Dialog */}
      <ConfirmDialog
        open={confirmDialog.open}
        title={confirmDialog.title}
        message={confirmDialog.message}
        confirmLabel={confirmDialog.confirmLabel || 'Delete'}
        cancelLabel={confirmDialog.cancelLabel || 'Cancel'}
        loading={isConfirmLoading}
        onConfirm={confirmDialog.onConfirm}
        onCancel={() => setConfirmDialog(prev => ({ ...prev, open: false }))}
      />
    </div>
  );
};

'use client';

import React, { useState, useEffect, useRef, useCallback } from 'react';
import Image from 'next/image';
import { Search, Plus, Copy, Edit, Trash, Lock, Layers, Download, Upload, CheckCircle2, Loader2, ChevronDown, Database } from 'lucide-react';
import { Product } from '@/types';
import { useProductStore } from '@/store/useProductStore';
import { useToastStore } from '@/store/useToastStore';
import { ResponsiveTableContainer } from '@/components/ui/ResponsiveTableContainer';
import { CustomDropdown } from '@/components/ui/CustomDropdown';
import { Button } from '@/components/ui/Button';
import { exportProductsToCSV, exportProductsToJSON } from '@/lib/dataTransferUtils';
import { ProductImportModal } from '@/components/admin/modals/ProductImportModal';
import { seedProductsToFirestore } from '@/hooks/useProductSync';
import { ConfirmDialog } from '@/components/ui/ConfirmDialog';
import { cn } from '@/lib/utils';

interface ProductsTabProps {
  products: Product[];
  adminProductSearch: string;
  setAdminProductSearch: (val: string) => void;
  adminProductCat: string;
  setAdminProductCat: (val: string) => void;
  lowStockOnly: boolean;
  setLowStockOnly: (val: boolean) => void;
  siteSettings: {
    lowStockThreshold: number;
  };
  resetToDefault: () => void;
  openAddProductModal: () => void;
  openEditProductModal: (product: Product) => void;
  duplicateProduct: (product: Product) => void;
  deleteProduct: (productId: string) => void;
}

export const ProductsTab: React.FC<ProductsTabProps> = ({
  products,
  adminProductSearch,
  setAdminProductSearch,
  adminProductCat,
  setAdminProductCat,
  lowStockOnly,
  setLowStockOnly,
  siteSettings,
  resetToDefault,
  openAddProductModal,
  openEditProductModal,
  duplicateProduct,
  deleteProduct,
}) => {
  const { updateProduct, quickAdjustStock, bulkAddProducts, replaceProducts } = useProductStore();
  const { addToast } = useToastStore();

  const [selectedProductIds, setSelectedProductIds] = useState<string[]>([]);
  const [activeBulkTab, setActiveBulkTab] = useState<'payments' | 'badges' | 'pricing' | null>(null);

  const [isConfirmLoading, setIsConfirmLoading] = useState(false);

  // Shared Confirmation Dialog State
  const [confirmDialog, setConfirmDialog] = useState<{
    open: boolean;
    title: string;
    message: string;
    confirmLabel?: string;
    cancelLabel?: string;
    onConfirm: () => void | Promise<void>;
  }>({
    open: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [isSyncingCatalog, setIsSyncingCatalog] = useState(false);
  const [productToast, setProductToast] = useState('');

  const [showSyncConfirm, setShowSyncConfirm] = useState(false);
  const [syncResult, setSyncResult] = useState<{ added: number; skipped: number } | null>(null);
  const [syncError, setSyncError] = useState<string | null>(null);

  // Infinite Scroll state for Admin Products Table
  const ADMIN_BATCH_SIZE = 15;
  const [visibleCount, setVisibleCount] = useState<number>(ADMIN_BATCH_SIZE);
  const [isLoadingMore, setIsLoadingMore] = useState<boolean>(false);
  const sentinelRef = useRef<HTMLDivElement | null>(null);

  const handleImportSuccess = () => {
    addToast('Products imported successfully!', 'success');
    setIsImportModalOpen(false);
  };

  const handleSyncCatalogToDatabase = () => {
    setShowSyncConfirm(true);
  };

  const handleConfirmSync = async () => {
    setIsSyncingCatalog(true);
    setSyncResult(null);
    setSyncError(null);
    try {
      const result = await seedProductsToFirestore();
      setSyncResult(result);
      setProductToast(`Catalog sync complete: Added ${result.added} new products, skipped ${result.skipped} existing.`);
      setTimeout(() => setProductToast(''), 5000);
    } catch (err: any) {
      console.error('Firestore catalog sync failed:', err);
      const errorMsg = err?.message || 'Failed to sync catalog to database.';
      setSyncError(errorMsg);
      setProductToast(`Sync error: ${errorMsg}`);
      setTimeout(() => setProductToast(''), 6000);
    } finally {
      setIsSyncingCatalog(false);
      setShowSyncConfirm(false);
    }
  };

  const handleResetCatalog = async () => {
    await resetToDefault();
    addToast('Catalog successfully reset to default factory products!', 'success');
  };

  const openResetCatalogConfirm = () => {
    setConfirmDialog({
      open: true,
      title: 'Reset product catalog',
      message: 'Are you sure you want to reset the entire product catalog back to the default list? All current products will be replaced by the default factory list.',
      confirmLabel: 'Reset',
      cancelLabel: 'Cancel',
      onConfirm: async () => {
        setIsConfirmLoading(true);
        try {
          await handleResetCatalog();
          setConfirmDialog(prev => ({ ...prev, open: false }));
        } finally {
          setIsConfirmLoading(false);
        }
      }
    });
  };

  const openSingleDeleteConfirm = (product: Product) => {
    setConfirmDialog({
      open: true,
      title: `Delete Product: ${product.name}`,
      message: `Are you sure you want to permanently delete "${product.name}"? This action cannot be undone.`,
      confirmLabel: 'Delete',
      cancelLabel: 'Cancel',
      onConfirm: async () => {
        setIsConfirmLoading(true);
        try {
          await deleteProduct(product.id);
          addToast(`Product "${product.name}" deleted successfully`, 'success');
          setConfirmDialog(prev => ({ ...prev, open: false }));
        } catch (err: any) {
          addToast('Failed to delete product', 'error');
        } finally {
          setIsConfirmLoading(false);
        }
      }
    });
  };

  const [bulkPaymentMethods, setBulkPaymentMethods] = useState<('cod' | 'bkash' | 'nagad' | 'card')[]>(['cod', 'bkash', 'nagad', 'card']);
  const [bulkBadges, setBulkBadges] = useState<{
    isFlashDeal: boolean | null;
    isBestDeal: boolean | null;
    isNew: boolean | null;
    isBrandMall: boolean | null;
    isTrending: boolean | null;
  }>({
    isFlashDeal: null,
    isBestDeal: null,
    isNew: null,
    isBrandMall: null,
    isTrending: null,
  });

  const [bulkStockVal, setBulkStockVal] = useState<string>('');
  const [bulkDiscountVal, setBulkDiscountVal] = useState<string>('');

  // Dropdown click-outside handler
  React.useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (activeBulkTab && !(event.target as HTMLElement).closest('.bulk-dropdown-container')) {
        setActiveBulkTab(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [activeBulkTab]);

  const handleBulkUpdate = () => {
    if (selectedProductIds.length === 0) return;

    selectedProductIds.forEach((id) => {
      const prod = products.find((p) => p.id === id);
      if (!prod) return;

      const updatedFields: Partial<Product> = {};

      // 1. Payment Methods
      updatedFields.allowedPaymentMethods = bulkPaymentMethods;

      // 2. Badges (Tri-state)
      if (bulkBadges.isFlashDeal !== null) updatedFields.isFlashDeal = bulkBadges.isFlashDeal;
      if (bulkBadges.isBestDeal !== null) updatedFields.isBestDeal = bulkBadges.isBestDeal;
      if (bulkBadges.isNew !== null) updatedFields.isNew = bulkBadges.isNew;
      if (bulkBadges.isBrandMall !== null) updatedFields.isBrandMall = bulkBadges.isBrandMall;
      if (bulkBadges.isTrending !== null) updatedFields.isTrending = bulkBadges.isTrending;

      // 3. Stock Adjustment
      if (bulkStockVal.trim() !== '') {
        const stockNum = parseInt(bulkStockVal, 10);
        if (!isNaN(stockNum)) {
          updatedFields.stockQuantity = stockNum;
          updatedFields.inStock = stockNum > 0;
        }
      }

      // 4. Discount / Price Adjustment
      if (bulkDiscountVal.trim() !== '') {
        const discountNum = parseFloat(bulkDiscountVal);
        if (!isNaN(discountNum) && discountNum >= 0 && discountNum <= 100) {
          const basePrice = prod.originalPrice || prod.price;
          const discounted = Math.round(basePrice * (1 - discountNum / 100));
          updatedFields.originalPrice = basePrice;
          updatedFields.price = discounted;
        }
      }

      updateProduct(id, updatedFields);
    });

    const msg = `Successfully bulk updated payment methods, badges, and inventory metrics for ${selectedProductIds.length} products!`;

    addToast(msg, 'success');
    setSelectedProductIds([]);
    setBulkStockVal('');
    setBulkDiscountVal('');
    setActiveBulkTab(null);
    setBulkBadges({
      isFlashDeal: null,
      isBestDeal: null,
      isNew: null,
      isBrandMall: null,
      isTrending: null,
    });
  };

  const filteredAdminProducts = products.filter((p) => {
    const searchLower = adminProductSearch.toLowerCase().trim();
    const matchesSearch = !searchLower ||
      p.name.toLowerCase().includes(searchLower) ||
      (p.sku && p.sku.toLowerCase().includes(searchLower));

    const matchesCat = adminProductCat === 'All' || p.category === adminProductCat;

    const threshold = p.lowStockThreshold ?? siteSettings.lowStockThreshold;
    const matchesLowStock = !lowStockOnly || (p.stockQuantity ?? 10) <= threshold;

    return matchesSearch && matchesCat && matchesLowStock;
  });

  // Reset infinite scroll batch when filters change
  useEffect(() => {
    setVisibleCount(ADMIN_BATCH_SIZE);
    setIsLoadingMore(false);
  }, [adminProductSearch, adminProductCat, lowStockOnly]);

  const displayedAdminProducts = filteredAdminProducts.slice(0, visibleCount);
  const hasMore = visibleCount < filteredAdminProducts.length;

  const handleLoadMore = useCallback(() => {
    if (isLoadingMore || visibleCount >= filteredAdminProducts.length) return;
    setIsLoadingMore(true);
    setTimeout(() => {
      setVisibleCount((prev) => Math.min(prev + ADMIN_BATCH_SIZE, filteredAdminProducts.length));
      setIsLoadingMore(false);
    }, 120);
  }, [isLoadingMore, visibleCount, filteredAdminProducts.length]);

  // IntersectionObserver for auto-scroll loading inside table
  useEffect(() => {
    if (!hasMore || isLoadingMore) return;
    const el = sentinelRef.current;
    if (!el) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) {
          handleLoadMore();
        }
      },
      {
        root: null,
        rootMargin: '200px',
        threshold: 0.1,
      }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [hasMore, isLoadingMore, handleLoadMore]);

  return (
    <div className="space-y-2">
      {/* Search & Action bar - Compact */}
      <div className="bg-white rounded-xl border border-zinc-200 p-2 sm:px-3 sm:py-2 flex flex-col gap-2 shadow-2xs">
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2 w-full lg:w-auto flex-1">
          <div className="relative w-full sm:min-w-[220px] sm:flex-1">
            <input
              type="text"
              value={adminProductSearch}
              onChange={(e) => setAdminProductSearch(e.target.value)}
              placeholder="Search SKU or Product name..."
              className="w-full h-8 pl-8 pr-2.5 text-xs bg-zinc-50 border border-zinc-200 rounded-lg focus:outline-hidden focus:border-primary focus:ring-1 focus:ring-primary"
            />
            <Search className="w-3.5 h-3.5 text-zinc-400 absolute left-2.5 top-1/2 -translate-y-1/2" />
          </div>

          <div className="w-full sm:w-auto min-w-[160px]">
            <CustomDropdown
              value={adminProductCat}
              onChange={(val) => setAdminProductCat(val)}
              searchable={false}
              options={[
                { value: 'All', label: 'All Categories' },
                { value: 'Electronics & Gadgets', label: 'Electronics' },
                { value: "Men's Fashion", label: "Men's Fashion" },
                { value: "Women's Fashion", label: "Women's Fashion" },
                { value: 'Kids & Baby Care', label: 'Kids & Baby' },
                { value: 'Home & Kitchen Appliances', label: 'Home & Kitchen' },
                { value: 'Beauty & Personal Care', label: 'Beauty & Personal Care' },
                { value: 'Footwear & Leather', label: 'Footwear' },
              ]}
              triggerClassName="h-8 px-2.5 text-xs bg-zinc-50 border-zinc-200"
              dropdownClassName="min-w-[180px]"
            />
          </div>
