          </table>
        </ResponsiveTableContainer>
      ) : (
        <div className="grid grid-cols-2 sm:grid-cols-2 lg:grid-cols-3 gap-3 sm:gap-4">
          {wishlistItems.map((p) => (
            <ProductCard key={p.id} product={p} />
