import { useUIStore } from '@/store/useUIStore';
import { useCartStore } from '@/store/useCartStore';
import { useWishlistStore } from '@/store/useWishlistStore';
import { useAuthStore } from '@/store/useAuthStore';
import { useOrderStore } from '@/store/useOrderStore';
import { useProductSync } from '@/hooks/useProductSync';
import { useCategorySync } from '@/hooks/useCategorySync';
import { auth } from '@/lib/firebase';
import { onAuthStateChanged } from 'firebase/auth';
import { ShieldAlert, ArrowLeftRight } from 'lucide-react';

export interface AppLayoutProps {
  children: React.ReactNode;
}

export function AppLayout({ children }: AppLayoutProps) {
  // Global Real-Time Firestore Product & Category Catalog Sync
  useProductSync();
  useCategorySync();

  const pathname = usePathname();
  const isAdminPanelActive = useUIStore((state) => state.isAdminPanelActive);
  const isAdminPage = pathname?.startsWith('/admin') || isAdminPanelActive;
  const isAccountPage = pathname?.startsWith('/account') || isAdminPage;

  const isCategoryDrawerOpen = useUIStore((state) => state.isCategoryDrawerOpen);
  const isSearchOpen = useUIStore((state) => state.isSearchOpen);
  const isCartOpen = useCartStore((state) => state.isCartOpen);
  const cartError = useCartStore((state) => state.cartError);
  const setCartError = useCartStore((state) => state.setCartError);

  // Auto-dismiss cart error after 5 seconds
  useEffect(() => {
    if (cartError) {
      const t = setTimeout(() => {
        setCartError(null);
      }, 5000);
      return () => clearTimeout(t);
    }
  }, [cartError, setCartError]);
  const isWishlistOpen = useWishlistStore((state) => state.isWishlistOpen);

  const { currentUser, exitImpersonation, updateUserDetails } = useAuthStore();

  // Automatic Session Restoration from Firebase Auth
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const { setAuthReady } = useAuthStore.getState();

    // Safety timer: mark auth as ready after 4 seconds regardless of Firebase response
    const safetyTimer = setTimeout(() => {
      setAuthReady(true);
    }, 4000);

    const unsubscribe = onAuthStateChanged(auth, async (fbUser) => {
      try {
        if (!fbUser) {
          setAuthReady(true);
          clearTimeout(safetyTimer);
          return;
        }

        const state = useAuthStore.getState();
        const localUser = state.currentUser;

        // If already matched, skip
        if (localUser && localUser.email.toLowerCase() === fbUser.email?.toLowerCase()) {
          setAuthReady(true);
          clearTimeout(safetyTimer);
          return;
        }

        // If impersonating, do not disrupt
        if (localUser?.impersonatingFromAdminEmail) {
          setAuthReady(true);
          clearTimeout(safetyTimer);
          return;
        }

        // Restore session from authoritative Firebase source
        await state.restoreSessionFromFirebase(fbUser);
      } catch (err) {
        console.warn('[AuthRestore] Failed:', err);
      } finally {
        setAuthReady(true);
        clearTimeout(safetyTimer);
      }
    });

    return () => {
      unsubscribe();
      clearTimeout(safetyTimer);
    };
  }, []);

  // Global Auth Sync: Authoritatively verify and sync user role from server whenever session refreshes
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const syncUserRole = async () => {
      const fbUser = auth.currentUser;
      if (!fbUser || !currentUser) return;

      try {
        const idToken = await fbUser.getIdToken();
        const res = await fetch('/api/auth/sync-role', {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${idToken}`,
            'Content-Type': 'application/json',
          },
        });

        if (res.ok) {
          const data = await res.json();
          if (data?.role && data.role !== currentUser.role) {
            console.log(`[AuthSync] Authoritative role update: ${currentUser.role} -> ${data.role}`);
            // Use updateUserDetails to only change role without losing other profile data
            updateUserDetails(currentUser.id, { role: data.role });
          }
        }
      } catch (err) {
        console.warn('[AuthSync] Role verification skipped:', err);
      }
    };

    // Initial sync on mount or user change
    syncUserRole();

    // Periodic sync every 15 minutes to handle background role updates
    const interval = setInterval(syncUserRole, 15 * 60 * 1000);
    return () => clearInterval(interval);
  }, [currentUser?.id, currentUser?.role, updateUserDetails, currentUser]);

  // Lock body scroll and prevent any background interaction when any drawer/overlay is active
  useEffect(() => {
    const isAnyOverlayActive = isCategoryDrawerOpen || isSearchOpen || isCartOpen || isWishlistOpen;
    if (isAnyOverlayActive) {
      document.body.style.overflow = 'hidden';
      document.body.style.touchAction = 'none';
    } else {
      document.body.style.overflow = '';
      document.body.style.touchAction = '';
    }
    return () => {
      document.body.style.overflow = '';
      document.body.style.touchAction = '';
    };
  }, [isCategoryDrawerOpen, isSearchOpen, isCartOpen, isWishlistOpen]);

  // Clean mock orders and conditionally subscribe to live Firestore orders for Admin or Account/Track routes
  useEffect(() => {
    if (typeof window === 'undefined') return;
    try {
      useOrderStore.getState().clearMockOrders();
      if (isAdminPage || pathname?.startsWith('/account') || pathname?.startsWith('/track')) {
        const unsub = useOrderStore.getState().syncWithFirestore();
        return () => {
          if (typeof unsub === 'function') {
            (unsub as () => void)();
          }
        };
      }
    } catch {
      // Ignore SSR/prerender sync errors
    }
  }, [isAdminPage, pathname]);

  return (
    <div className="flex flex-col min-h-dvh bg-app-bg">
      {currentUser?.impersonatingFromAdminEmail && (
        <div className="bg-amber-400 text-zinc-950 font-bold text-xs py-2.5 px-4 sticky top-0 z-50 flex items-center justify-between shadow-md border-b border-amber-500 font-sans">
          <div className="flex items-center gap-2">
            <ShieldAlert className="w-4 h-4 text-zinc-950 animate-pulse shrink-0" />
            <span>
              {`ADMIN ACT-AS IMPERSONATION MODE: Logged in as customer "${currentUser.name}" (${currentUser.email}).`}
            </span>
          </div>
          <button
            onClick={() => {
              exitImpersonation();
            }}
            className="px-3 py-1 bg-zinc-950 text-white rounded-lg hover:bg-zinc-800 transition-colors flex items-center gap-1 font-extrabold cursor-pointer text-2xs"
          >
            <ArrowLeftRight className="w-3 h-3" />
            <span>{'Exit Act-As'}</span>
          </button>
        </div>
      )}
      <DynamicThemeStyles />
      {/* Top Loading Progress Bar for Instant Page Navigation Feedback */}
      <LoadingBar />

      {/* Floating Auto-Hide Overlay Scroll Indicator */}
      <AutoScrollIndicator />

      {/* Top Navbar (Desktop) - Hidden ONLY on Admin Dashboard */}
      {!isAdminPage && <TopNavbar />}

      {/* Mobile Top Header - Hidden ONLY on Admin Dashboard */}
      {!isAdminPage && <MobileHeader />}

      {/* Main Page Content - pb-20 on mobile (except admin pages) */}
      <main className={`flex-1 w-full ${isAdminPage ? 'pb-0' : 'pb-20 md:pb-0'}`}>
        {children}
      </main>

      {/* Footer - Hidden ONLY on Admin Dashboard */}
      {!isAdminPage && <Footer />}

      {/* Mobile Native Bottom Navigation Bar - Hidden on Admin Dashboard */}
      {!isAdminPage && <MobileBottomNav />}

      {/* Global Interactive Drawers & Modals (Pure CSS transitions, zero lag) */}
      <CartDrawer />
      <WishlistDrawer />
      <CategoryDrawer />
      <SearchModal />

      {/* Global Cart Error Floating Toast */}
      {cartError && (
        <div className="fixed bottom-6 right-6 z-[200] max-w-sm p-4 bg-zinc-900 border border-zinc-800 text-white rounded-2xl shadow-2xl flex items-start gap-3 animate-in slide-in-from-bottom-5 fade-in duration-200">
          <div className="w-5 h-5 rounded-full bg-red-500/15 text-red-400 flex items-center justify-center shrink-0 mt-0.5 font-bold text-xs">
            ✕
          </div>
          <div className="space-y-1 select-none flex-1">
            <h4 className="font-extrabold text-xs tracking-wider uppercase text-zinc-300">Cart Alert</h4>
            <p className="text-2xs sm:text-xs text-zinc-400 leading-normal font-medium">{cartError}</p>
          </div>
          <button
            type="button"
            onClick={() => setCartError(null)}
            className="text-zinc-500 hover:text-white transition-colors cursor-pointer text-xs p-0.5 shrink-0 animate-in fade-in"
          >
            ✕
          </button>
        </div>
      )}

      {/* Global Toast Notifications */}
      <ToastContainer />
    </div>
  );
}

/**
 * @file components/layout/CategoryDrawer.tsx
 * @description Dedicated Slide-In Category Navigation Drawer.
 * Clean, focused Category Menu with Category Title, Category Search, and Nested Accordion categories.
 */

'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { 
  X, 
  ChevronRight, 
  ChevronDown,
  LayoutGrid, 
  Search,
  ArrowRight,
  Sparkles
} from 'lucide-react';
import { useUIStore } from '@/store/useUIStore';
import { useCategoryStore } from '@/store/useCategoryStore';
import { SubCategoryItem } from '@/types';

export function CategoryDrawer() {
  const { isCategoryDrawerOpen, closeCategoryDrawer } = useUIStore();
  const { categories } = useCategoryStore();

  const [searchTerm, setSearchTerm] = useState('');
  // Start with all category accordions CLOSED by default
  const [expandedCategoryId, setExpandedCategoryId] = useState<string | null>(null);
  const [mounted, setMounted] = React.useState(false);

  React.useEffect(() => {
    const timer = setTimeout(() => setMounted(true), 0);
    return () => clearTimeout(timer);
  }, []);

  // Reset expanded category and search term whenever drawer is closed
  React.useEffect(() => {
    if (!isCategoryDrawerOpen) {
      setExpandedCategoryId(null);
      setSearchTerm('');
    }
  }, [isCategoryDrawerOpen]);



  const toggleExpand = (catId: string) => {
    setExpandedCategoryId((prev) => (prev === catId ? null : catId));
  };

  const getSubcategoryName = (sub: string | SubCategoryItem) => {
    if (typeof sub === 'string') return sub;
    return sub.name;
  };

  const getSubcategoryRawName = (sub: string | SubCategoryItem) => {
    if (typeof sub === 'string') return sub;
    return sub.name;
  };

  const filteredCategories = React.useMemo(() => {
    if (!searchTerm.trim()) return categories || [];
    const term = searchTerm.toLowerCase().trim();
    return (categories || []).filter((cat) => {
      const matchParent = cat.name.toLowerCase().includes(term);
      const matchSub = cat.subcategories?.some((s) => {
        const name = typeof s === 'string' ? s : s.name;
        return name.toLowerCase().includes(term);
      });
      return matchParent || matchSub;
    });
  }, [categories, searchTerm]);

  return (
    <>
      {/* Backdrop */}
      <div
        className={`pure-drawer-backdrop ${isCategoryDrawerOpen ? 'is-open' : ''}`}
        onClick={closeCategoryDrawer}
        aria-hidden={!isCategoryDrawerOpen}
      />

      {/* Slide-In Categories Drawer */}
      <aside
        className={`pure-drawer-panel drawer-left flex flex-col bg-white ${
          isCategoryDrawerOpen ? 'is-open' : ''
        }`}
        role="dialog"
        aria-modal="true"
        aria-label={'Categories'}
      >
        {/* Header: Category Title + Close Button */}
        <div className="flex items-center justify-between px-4 py-3.5 border-b border-zinc-200 bg-zinc-950 text-white">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-lg bg-primary/20 border border-primary/40 flex items-center justify-center text-primary">
              <LayoutGrid className="w-4.5 h-4.5 text-white" />
            </div>
            <div>
              <h2 className="font-sans font-bold text-sm tracking-tight text-white block leading-tight">
                {'Categories'}
              </h2>
              <span className="text-2xs text-zinc-400 font-mono">
                {categories.length} {'Available'}
              </span>
            </div>
          </div>

          <button
            type="button"
            onClick={closeCategoryDrawer}
            className="p-1.5 text-zinc-400 hover:text-white rounded-lg hover:bg-zinc-800 transition-colors cursor-pointer"
            aria-label="Close drawer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Quick Search */}
        <div className="p-3 bg-zinc-50 border-b border-zinc-200/80">
          <div className="relative">
            <input
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder={'Search categories or subcategories...'}
              className="w-full h-8.5 pl-8 pr-7 text-xs bg-white border border-zinc-200 rounded-lg text-zinc-900 placeholder:text-zinc-400 focus:outline-hidden focus:border-primary"
            />
            <Search className="w-3.5 h-3.5 text-zinc-400 absolute left-2.5 top-1/2 -translate-y-1/2 pointer-events-none" />
            {searchTerm && (
              <button
                type="button"
                onClick={() => setSearchTerm('')}
                className="absolute right-2 top-1/2 -translate-y-1/2 p-0.5 text-zinc-400 hover:text-zinc-600 cursor-pointer"
              >
                <X className="w-3 h-3" />
              </button>
            )}
          </div>
        </div>

        {/* "All Categories" Top Anchor - Pinned Row */}
        <div className="border-b border-zinc-200/50">
          <Link
            href="/category"
            onClick={closeCategoryDrawer}
            className="flex items-center gap-3 px-4 py-3 bg-zinc-50 hover:bg-primary/10 hover:text-primary transition-colors font-bold text-xs text-zinc-900 border-l-4 border-primary"
          >
            <div className="w-7 h-7 rounded-lg bg-primary/10 flex items-center justify-center text-primary">
              <LayoutGrid className="w-3.5 h-3.5" />
            </div>
            <span>{'All Categories Index'}</span>
          </Link>
        </div>

        {/* Scrollable Categories Accordion List */}
        <div className="flex-1 overflow-y-auto custom-scrollbar-thin divide-y divide-zinc-100">

          {/* Nested Categories List with Images & Zero-Shift Layout */}
          {filteredCategories.length === 0 ? (
            <div className="text-center py-10 px-4 text-zinc-400 text-xs font-medium">
              {'No matching categories found'}
            </div>
          ) : (
            filteredCategories.map((cat) => {
              const isExpanded = expandedCategoryId === cat.id;
              const hasSubs = cat.subcategories && cat.subcategories.length > 0;

              return (
                <div key={cat.id || cat.name} className="bg-white">
                  {/* Parent Category Row - Position relative with absolute indicator bar to prevent layout push */}
                  <div
                    onClick={() => {
                      if (hasSubs) {
                        toggleExpand(cat.id);
                      } else {
                        closeCategoryDrawer();
                        window.location.href = `/shop?category=${encodeURIComponent(cat.name)}`;
                      }
                    }}
                    className={`relative flex items-center justify-between pl-4 pr-4 py-2.5 cursor-pointer transition-colors font-semibold overflow-hidden ${
                      isExpanded 
                        ? 'bg-primary/10 text-primary' 
                        : 'text-zinc-900 hover:bg-zinc-100/80 hover:text-primary'
                    }`}
                  >
                    {isExpanded && (
                      <div className="absolute left-0 top-0 bottom-0 w-1 bg-primary" />
                    )}

                    <div className="flex items-center gap-3 min-w-0">
                      {/* Category Thumbnail Image */}
                      <div className={`relative w-8 h-8 rounded-lg overflow-hidden border shrink-0 bg-zinc-100 shadow-2xs ${
                        isExpanded ? 'border-primary/40' : 'border-zinc-200'
                      }`}>
                        <Image
                          src={cat.image || '/placeholder-category.svg'}
                          alt={cat.name}
                          fill
                          sizes="32px"
                          referrerPolicy="no-referrer"
                          className="object-cover"
                        />
                      </div>
                      <span className={`text-xs truncate font-semibold ${isExpanded ? 'text-primary' : 'text-zinc-900'}`}>
                        {cat.name}
                      </span>
                    </div>

                    {hasSubs && (
                      <div className="p-1 text-zinc-400">
                        {isExpanded ? (
                          <ChevronDown className="w-4 h-4 text-primary" />
                        ) : (
                          <ChevronRight className="w-4 h-4 text-zinc-400" />
                        )}
                      </div>
                    )}
                  </div>

                  {/* Nested Subcategories Accordion Content */}
                  {isExpanded && hasSubs && (
                    <div className="bg-zinc-50/80 px-4 py-2 space-y-1.5 border-l-2 border-primary/40 ml-4 my-1 rounded-r-xl">
                      {cat.subcategories!.map((sub, idx) => {
                        const subName = getSubcategoryName(sub);
                        const rawName = getSubcategoryRawName(sub);
                        return (
                          <Link
                            key={idx}
                            href={`/shop?category=${encodeURIComponent(cat.name)}&q=${encodeURIComponent(rawName)}`}
                            onClick={closeCategoryDrawer}
                            className="flex items-center justify-between px-3 py-2 rounded-xl bg-white hover:bg-primary/10 border border-zinc-200/80 hover:border-primary/30 text-xs font-semibold text-zinc-700 hover:text-primary transition-colors shadow-2xs"
                          >
                            <span className="truncate">{subName}</span>
                            <ChevronRight className="w-3.5 h-3.5 text-zinc-400 shrink-0" />
                          </Link>
                        );
                      })}

                      {/* Quick Link to Browse Entire Parent Category */}
                      <div className="pt-2 border-t border-zinc-200/80 mt-2">
                        <Link
                          href={`/shop?category=${encodeURIComponent(cat.name)}`}
                          onClick={closeCategoryDrawer}
                          className="inline-flex items-center gap-1 text-2xs font-bold text-primary hover:underline uppercase tracking-wider"
                        >
                          <span>{'Browse All In Category →'}</span>
                        </Link>
                      </div>
                    </div>
                  )}
                </div>
              );
            })
          )}
        </div>

        {/* Footer: Direct Shopping Link */}
        <div className="p-3 border-t border-zinc-200 bg-zinc-50">
          <Link
            href="/shop"
            onClick={closeCategoryDrawer}
            className="flex items-center justify-center gap-2 w-full py-2.5 px-4 rounded-xl bg-primary hover:bg-primary-hover text-white text-xs font-bold transition-colors shadow-xs cursor-pointer"
          >
            <Sparkles className="w-3.5 h-3.5 text-white" />
            <span className="text-white">{'Browse All Products'}</span>
            <ArrowRight className="w-3.5 h-3.5 text-white" />
          </Link>
        </div>
      </aside>
    </>
  );
}

