/**
 * @file components/layout/SearchModal.tsx
 * @description Clean, minimalist floating live-search dropdown with instant matching products,
 * live price & rating preview, and simple trending searches without cluttering category tabs.
 */

'use client';

import React, { useEffect, useRef, useMemo } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { useRouter } from 'next/navigation';
import { 
  Search, 
  X, 
  TrendingUp, 
  Star, 
  ArrowRight,
  Truck,
  Flame
} from 'lucide-react';
import { useUIStore } from '@/store/useUIStore';
import { formatBDT } from '@/lib/formatCurrency';
import { useProductStore } from '@/store/useProductStore';

export function SearchModal() {
  const products = useProductStore((state) => state.products);
  const { isSearchOpen, closeSearch, searchQuery, setSearchQuery } = useUIStore();
  const router = useRouter();
  const inputRef = useRef<HTMLInputElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isSearchOpen) {
      setTimeout(() => {
        inputRef.current?.focus();
      }, 50);
    }
  }, [isSearchOpen]);

  // Handle ESC key to close
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isSearchOpen) {
        closeSearch();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isSearchOpen, closeSearch]);

  const trendingTags = useMemo(() => [
    { en: 'Smartwatch' },
    { en: 'Panjabi' },
    { en: 'Air Fryer' },
    { en: 'Wireless Earbuds' },
    { en: 'Polo Shirt' },
    { en: 'Jamdani Saree' },
    { en: 'Leather Loafers' },
    { en: 'Oud Attar' },
  ], []);

  // Filter products live directly matching name, category, brand, subcategory
  const filteredProducts = useMemo(() => {
    if (!searchQuery.trim()) return [];
    const query = searchQuery.toLowerCase().trim();

    return products.filter((p) => {
      return (
        p.name.toLowerCase().includes(query) ||
        p.category.toLowerCase().includes(query) ||
        p.subcategory.toLowerCase().includes(query) ||
        p.brand.toLowerCase().includes(query) ||
        p.description.toLowerCase().includes(query)
      );
    }).slice(0, 7);
  }, [searchQuery]);

  if (!isSearchOpen) return null;

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      const q = searchQuery.trim();
      closeSearch();
      router.push(`/shop?q=${encodeURIComponent(q)}`);
    }
  };

  const handleClearInput = () => {
    setSearchQuery('');
    inputRef.current?.focus();
  };

  const handleProductClick = () => {
    closeSearch();
  };

  const handleTagClick = (tagText: string) => {
    setSearchQuery(tagText);
    inputRef.current?.focus();
  };

  return (
    <div 
      className="fixed inset-0 z-[9999] flex flex-col items-center justify-start p-2.5 sm:p-4 md:p-8 bg-zinc-950/40 backdrop-blur-xs animate-in fade-in duration-150"
      onClick={(e) => {
        // If clicking backdrop outside floating container, close search
        if (e.target === e.currentTarget) {
          closeSearch();
        }
      }}
    >
      {/* Floating Search Container Card */}
      <div 
        ref={containerRef}
        className="w-full max-w-2xl bg-white rounded-2xl shadow-2xl border border-zinc-200 overflow-hidden flex flex-col max-h-[85dvh] sm:max-h-[80dvh] animate-in zoom-in-95 duration-150"
      >
        {/* Top Search Input Bar */}
        <div className="p-3 sm:p-3.5 border-b border-zinc-100 bg-white sticky top-0 z-20">
          <form onSubmit={handleSearchSubmit} className="relative flex items-center gap-2">
            <div className="relative flex-1 flex items-center">
              <Search className="w-5 h-5 text-primary absolute left-3.5 pointer-events-none" />
              <input
                ref={inputRef}
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder={'Search for products or brands...'}
                className="w-full h-11 sm:h-12 pl-11 pr-10 bg-zinc-50 hover:bg-zinc-100/80 focus:bg-white rounded-xl text-xs sm:text-sm font-medium text-zinc-900 placeholder:text-zinc-400 focus:outline-hidden border border-zinc-200 focus:border-primary focus:ring-2 focus:ring-primary/15 transition-all"
              />
              {searchQuery && (
                <button
                  type="button"
                  onClick={handleClearInput}
                  className="absolute right-3 p-1 rounded-full text-zinc-400 hover:text-zinc-800 hover:bg-zinc-200/70 transition-colors cursor-pointer"
                  aria-label="Clear input"
                >
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>

            {/* Submit button */}
            <button
              type="submit"
              className="h-11 sm:h-12 px-4 rounded-xl bg-primary hover:bg-primary-hover text-app-inverse text-xs font-bold uppercase tracking-wider transition-all flex items-center gap-1.5 shadow-xs shrink-0 cursor-pointer active:scale-95"
            >
              <span>{'Search'}</span>
            </button>

            {/* Close Button */}
            <button
              type="button"
              onClick={closeSearch}
              className="p-2 sm:p-2.5 rounded-xl text-zinc-400 hover:text-zinc-700 hover:bg-zinc-100 transition-colors cursor-pointer shrink-0"
              aria-label="Close search"
              title="Close (ESC)"
            >
              <X className="w-5 h-5" />
            </button>
          </form>
        </div>

        {/* Floating Live Results Body */}
        <div className="flex-1 overflow-y-auto p-3 sm:p-4 scrollbar-thin">
          {searchQuery.trim() === '' ? (
            /* Empty State: Simple Trending Keyword Tags */
            <div className="py-2">
              <div className="flex items-center gap-1.5 text-xs font-bold text-primary uppercase tracking-wider mb-2.5">
                <TrendingUp className="w-4 h-4 text-primary" />
                <span>{'Trending Searches'}</span>
              </div>
              <div className="flex flex-wrap gap-2">
                {trendingTags.map((tag) => (
                  <button
                    key={tag.en}
                    type="button"
                    onClick={() => handleTagClick(tag.en)}
                    className="flex items-center gap-1.5 px-3.5 py-1.5 rounded-full bg-zinc-100 hover:bg-zinc-900 hover:text-white text-xs font-semibold text-zinc-800 transition-all border border-zinc-200/80 cursor-pointer active:scale-95 group"
                  >
                    <Flame className="w-3 h-3 text-brand-gold group-hover:text-amber-400" />
                    <span>{tag.en}</span>
                  </button>
                ))}
              </div>
            </div>
          ) : (
            /* Live Filtered Products List */
            <div>
              <div className="flex items-center justify-between text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">
                <span>{'Live Results'} ({filteredProducts.length})</span>
              </div>

              {filteredProducts.length === 0 ? (
                <div className="text-center py-10">
                  <div className="w-12 h-12 rounded-full bg-zinc-100 text-zinc-400 flex items-center justify-center mx-auto mb-2.5">
                    <Search className="w-6 h-6" />
                  </div>
                  <p className="text-sm font-semibold text-zinc-700 mb-1">
                    {`No products found for "${searchQuery}"`}
                  </p>
                  <p className="text-xs text-zinc-400 mb-4">
                    {'Try checking your spelling or search for another item'}
                  </p>
                  <button
                    type="button"
                    onClick={() => {
                      closeSearch();
                      router.push('/shop');
                    }}
                    className="px-4 py-2 rounded-xl bg-zinc-900 text-white text-xs font-bold hover:bg-primary transition-colors cursor-pointer"
                  >
                    {'Browse All Products'}
                  </button>
                </div>
              ) : (
                <div className="divide-y divide-zinc-100">
                  {filteredProducts.map((p) => {
                    const isFreeShip = p.price >= 999;
                    return (
                      <Link
                        key={p.id}
                        href={`/product/${p.id}`}
                        onClick={handleProductClick}
                        className="flex items-center gap-3.5 py-2.5 px-2 hover:bg-zinc-50 rounded-xl transition-all group cursor-pointer"
                      >
                        {/* Product Thumbnail */}
                        <div className="relative w-13 h-14 rounded-xl overflow-hidden bg-zinc-100 border border-zinc-200/80 shrink-0 shadow-2xs">
                          <Image
                            src={p.images[0]}
                            alt={p.name}
                            fill
                            sizes="56px"
                            referrerPolicy="no-referrer"
                            className="object-cover group-hover:scale-108 transition-transform duration-300"
                          />
                          {p.discountPercent && p.discountPercent > 0 ? (
                            <span className="absolute top-1 left-1 px-1 py-0.2 rounded bg-primary text-app-inverse text-2xs font-black uppercase">
                              -{p.discountPercent}%
                            </span>
                          ) : null}
                        </div>

                        {/* Details */}
                        <div className="flex-1 min-w-0">
                          <p className="text-xs sm:text-sm font-semibold text-zinc-900 group-hover:text-primary transition-colors truncate">
                            {p.name}
                          </p>

                          <div className="flex items-center gap-2 mt-0.5">
                            <span className="text-2xs font-bold text-primary uppercase tracking-wider truncate">
                              {p.category}
                            </span>
                            <span className="text-zinc-300 text-xs">•</span>
                            <div className="flex items-center gap-0.5 text-2xs font-semibold text-zinc-600">
                              <Star className="w-2.5 h-2.5 text-amber-400 fill-amber-400" />
                              <span>{p.rating}</span>
                              <span className="text-zinc-400 text-2xs font-normal">({p.reviewCount || 12})</span>
                            </div>
                            {isFreeShip && (
                              <span className="hidden sm:inline-flex items-center gap-0.5 text-2xs font-bold text-amber-800 bg-amber-50 border border-amber-200/60 px-1 py-0.2 rounded">
                                <Truck className="w-2.5 h-2.5 text-amber-600" />
                                {'Free Ship'}
                              </span>
                            )}
                          </div>
                        </div>

                        {/* Price Column */}
                        <div className="text-right shrink-0">
                          <div className="text-xs sm:text-sm font-bold text-zinc-900 font-mono">
                            {formatBDT(p.price)}
                          </div>
                          {p.originalPrice && p.originalPrice > p.price && (
                            <div className="text-2xs text-zinc-400 line-through font-mono">
                              {formatBDT(p.originalPrice)}
                            </div>
                          )}
                        </div>
                      </Link>
                    );
                  })}
                </div>
              )}
            </div>
          )}
        </div>

        {/* Footer Action Bar */}
        {searchQuery.trim() !== '' && filteredProducts.length > 0 && (
          <div className="p-3 bg-zinc-50 border-t border-zinc-200/80 flex items-center justify-between">
            <span className="text-xs text-zinc-500 font-medium truncate">
              {`More results for "${searchQuery}"`}
            </span>
            <button
              type="button"
              onClick={() => {
                const q = searchQuery;
                closeSearch();
                router.push(`/shop?q=${encodeURIComponent(q)}`);
              }}
              className="px-3.5 py-1.5 bg-primary hover:bg-primary-hover text-app-inverse rounded-xl text-xs font-bold transition-all flex items-center gap-1 shadow-xs cursor-pointer active:scale-95 shrink-0"
            >
              <span>{'View All'}</span>
              <ArrowRight className="w-3.5 h-3.5" />
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * @file components/product/ProductCard.tsx
 * @description Unified, world-class e-commerce product card used consistently across all store pages.
 * Supports both:
 * 1. 'grid' layout (Compact, uniform height e-commerce card with badges, rating, pricing, and cart button)
 * 2. 'list' layout (True horizontal card with square image on left and structured details on right for all screen sizes)
 */

'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { Heart, Star, Check, Flame, ShoppingBag, Truck } from 'lucide-react';
import { Product } from '@/types';
import { useCartStore } from '@/store/useCartStore';
import { useWishlistStore } from '@/store/useWishlistStore';
import { useSiteSettingsStore } from '@/store/useSiteSettingsStore';
import { useHydrated } from '@/hooks/useHydrated';
import { formatBDT } from '@/lib/formatCurrency';
import { 
  normalizeProductMedia, 
  getProductHoverGif, 
  getProductDisplayImage,
  getProductSecondaryImage
} from '@/lib/mediaUtils';

export interface ProductCardProps {
  product: Product;
  priority?: boolean;
  layout?: 'grid' | 'list';
}

export const ProductCard = React.memo(function ProductCard({ 
  product, 
  priority = false,
  layout = 'grid'
}: ProductCardProps) {
  const showDiscountBadge = useSiteSettingsStore((state) => state.showDiscountBadge ?? true);
  const showFlashBadge = useSiteSettingsStore((state) => state.showFlashBadge ?? true);
  const showTrendingBadge = useSiteSettingsStore((state) => state.showTrendingBadge ?? true);
  const showHotDealBadge = useSiteSettingsStore((state) => state.showHotDealBadge ?? true);
  const showNewBadge = useSiteSettingsStore((state) => state.showNewBadge ?? true);

  const addItem = useCartStore((state) => state.addItem);
  const toggleWishlist = useWishlistStore((state) => state.toggleWishlist);
  const wishlisted = useWishlistStore((state) => state.items.some((item) => item.id === product.id));

  const hydrated = useHydrated();
  const inWishlist = hydrated && wishlisted;
  const [isHovered, setIsHovered] = useState(false);
  const [added, setAdded] = useState(false);

  // Extract media items in admin-defined sequence
  const mediaList = React.useMemo(() => normalizeProductMedia(product), [product]);
  const primaryMedia = mediaList[0];
  const hoverGif = React.useMemo(() => getProductHoverGif(product), [product]);

  const primaryImage = React.useMemo(() => getProductDisplayImage(product), [product]);
  const secondaryImage = React.useMemo(() => getProductSecondaryImage(product), [product]);

  const [imgSrc, setImgSrc] = useState<string>(primaryImage);

  // Keep imgSrc updated if product primary image changes
  React.useEffect(() => {
    setImgSrc(primaryImage);
  }, [primaryImage]);

  const discountPercent = product.originalPrice && product.originalPrice > product.price
    ? Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100)
    : (product.discountPercent || null);

  const savingsAmount = product.originalPrice && product.originalPrice > product.price
    ? Math.round(product.originalPrice - product.price)
    : 0;

  const handleAddToCart = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    addItem(product);
    setAdded(true);
    setTimeout(() => setAdded(false), 1500);
  };

  const handleToggleWishlist = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    toggleWishlist(product);
  };

  const displayName = product.name;
  const displayCategory = product.category;

  /* ========================================================================
   * 1. LIST VIEW LAYOUT (TRUE HORIZONTAL ROW ON MOBILE & DESKTOP)
   * ======================================================================== */
  if (layout === 'list') {
    return (
      <article 
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        className="group relative flex flex-row items-stretch bg-white rounded-2xl border border-border-color/90 shadow-2xs hover:shadow-md hover:border-border-hover transition-all duration-200 overflow-hidden p-2.5 sm:p-4 gap-3 sm:gap-4.5 gpu-smooth w-full"
      >
        {/* Left Side: Square Product Image with Badges & Wishlist */}
        <div className="relative w-28 h-28 sm:w-36 sm:h-36 md:w-44 md:h-44 aspect-square rounded-xl overflow-hidden bg-surface-subtle border border-border-color/60 shrink-0">
          <Link href={`/product/${product.id}`} prefetch={false} className="block w-full h-full relative cursor-pointer z-1">
            {/* Primary Cover Image */}
            <Image
              src={imgSrc}
              alt={displayName}
              fill
              sizes="(max-width: 640px) 112px, 176px"
              priority={priority}
              loading={priority ? undefined : "lazy"}
              unoptimized={primaryMedia?.type === 'gif'}
              referrerPolicy="no-referrer"
              onError={() => {
                setImgSrc('https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=800&auto=format&fit=crop&q=80');
              }}
              className={`object-cover object-center transition-all duration-300 ease-out ${
                isHovered && ((hoverGif && hoverGif !== imgSrc) || secondaryImage)
                  ? 'opacity-0 scale-105' 
                  : 'opacity-100 group-hover:scale-105'
              }`}
            />

            {/* Hover Animated GIF preview - Only mounted on hover to prevent massive page load delay */}
            {isHovered && hoverGif && hoverGif !== imgSrc && (
              <Image
                src={hoverGif}
                alt={`${displayName} Animated Preview`}
                fill
                unoptimized
                sizes="(max-width: 640px) 112px, 176px"
                referrerPolicy="no-referrer"
                className="object-cover object-center absolute inset-0 transition-opacity duration-300 ease-out opacity-100 scale-105"
              />
            )}

            {/* Secondary Alternate Image on Hover - Only mounted on hover */}
            {isHovered && !hoverGif && secondaryImage && (
              <Image
                src={secondaryImage}
                alt={`${displayName} Alternate`}
                fill
                sizes="(max-width: 640px) 112px, 176px"
                referrerPolicy="no-referrer"
                className="object-cover object-center absolute inset-0 transition-opacity duration-300 ease-out opacity-100 scale-105"
              />
            )}
          </Link>

          {/* Top-Left: Discount Badges */}
          <div className="absolute top-1.5 left-1.5 sm:top-2 sm:left-2 flex flex-col gap-1 z-10 pointer-events-none">
            {discountPercent && (showDiscountBadge !== false) && (product.showDiscountBadge !== false) && (
              <span className="px-1.5 py-0.5 rounded-md bg-primary text-white text-2xs sm:text-2xs font-black uppercase tracking-wider shadow-xs">
                -{discountPercent}%
              </span>
            )}
            {product.isFlashDeal && (showFlashBadge !== false) && (product.showFlashBadge !== false) && (
              <span className="px-1.5 py-0.5 rounded-md bg-amber-500 text-white text-2xs font-bold uppercase tracking-wider shadow-xs flex items-center gap-0.5">
                <Flame className="w-2.5 h-2.5 fill-current text-white" />
                <span className="hidden sm:inline">HOT</span>
              </span>
            )}
          </div>

          {/* Top-Right: Wishlist Heart */}
          <button
            type="button"
            onClick={handleToggleWishlist}
            aria-label={inWishlist ? 'Remove from wishlist' : 'Add to wishlist'}
            className={`absolute top-1.5 right-1.5 sm:top-2 sm:right-2 z-10 w-6.5 h-6.5 sm:w-7.5 sm:h-7.5 rounded-full border transition-all flex items-center justify-center cursor-pointer ${
              inWishlist 
                ? 'bg-primary border-primary text-white shadow-xs' 
                : 'bg-white/90 backdrop-blur-xs hover:bg-white border-border-color text-text-muted hover:text-primary shadow-2xs'
            }`}
          >
            <Heart className={`w-3.5 h-3.5 ${inWishlist ? 'fill-current text-white' : ''}`} />
          </button>
        </div>

        {/* Right Side: Structured Details, Pricing & Cart Action */}
        <div className="flex-1 min-w-0 flex flex-col justify-between self-stretch py-0.5 sm:py-1">
          <div>
            {/* Category & Star Rating */}
            <div className="flex items-center justify-between gap-1 mb-1">
              <span className="text-2xs sm:text-2xs font-bold uppercase tracking-wider text-text-muted truncate min-w-0">
                {displayCategory}
              </span>

              <div className="flex items-center gap-0.5 sm:gap-1 text-2xs sm:text-2xs font-bold text-text-main bg-surface-subtle px-1.5 py-0.5 rounded-md border border-border-color shrink-0">
                <Star className="w-2.5 h-2.5 sm:w-3 sm:h-3 fill-amber-400 text-amber-500 shrink-0" />
                <span className="font-extrabold">{product.rating ? (product.rating ?? 0).toFixed(1) : '4.8'}</span>
                <span className="text-text-muted font-normal hidden sm:inline">({product.reviewCount ?? 34})</span>
              </div>
            </div>

            {/* Product Title (2-Line Clamp) */}
            <h3 className="text-xs sm:text-sm md:text-base font-bold text-text-main group-hover:text-primary transition-colors leading-snug line-clamp-2">
              <Link href={`/product/${product.id}`} prefetch={false} className="hover:underline">
                {displayName}
              </Link>
            </h3>

            {/* Specs / Description snippet (desktop / tablet) */}
            <p className="hidden sm:line-clamp-1 text-xs text-text-muted mt-1 leading-relaxed">
              {product.description}
            </p>

            {/* Color Swatches if available */}
            {product.colors && product.colors.length > 0 && (
              <div className="flex items-center gap-1.5 mt-1.5">
                <span className="text-2xs sm:text-2xs text-text-muted font-medium hidden sm:inline">
                  {'Colors:'}
                </span>
                <div className="flex items-center gap-1">
                  {product.colors.slice(0, 4).map((c, i) => (
                    <span 
                      key={i}
                      title={c.name}
                      style={{ backgroundColor: c.hex }}
                      className="w-2.5 h-2.5 sm:w-3 sm:h-3 rounded-full border border-border-hover shadow-2xs"
                    />
                  ))}
                  {product.colors.length > 4 && (
                    <span className="text-2xs text-text-muted font-medium">+{product.colors.length - 4}</span>
                  )}
                </div>
              </div>
            )}

            {/* Reassurance Tag */}
            <div className="flex items-center gap-1.5 mt-1 sm:mt-1.5 text-2xs sm:text-2xs text-emerald-700 font-bold truncate">
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-600 shrink-0" />
              <span className="truncate">{'In Stock • 2-3 Days Delivery'}</span>
            </div>
          </div>

          {/* Bottom Bar: Price & Add to Cart Button */}
          <div className="mt-auto pt-2 border-t border-border-color/60 flex items-center justify-between gap-2">
            {/* Pricing Section */}
            <div className="flex items-baseline gap-1.5 flex-wrap">
              <span className="text-sm sm:text-lg font-black text-text-main font-sans tracking-tight">
                {formatBDT(product.price)}
              </span>
              {product.originalPrice && product.originalPrice > product.price && (
                <span className="text-2xs sm:text-xs text-text-subtle line-through font-semibold">
                  {formatBDT(product.originalPrice)}
                </span>
              )}
              {discountPercent && (
                <span className="text-2xs sm:text-2xs font-bold text-emerald-700 bg-emerald-50 border border-emerald-200 px-1.5 py-0.2 rounded hidden xs:inline">
                  {savingsAmount > 0 ? `৳${savingsAmount} ছাড়` : `-${discountPercent}%`}
                </span>
              )}
            </div>

            {/* Cart Button */}
            <button
              type="button"
              onClick={handleAddToCart}
              className={`h-7 sm:h-8.5 px-3 sm:px-4 rounded-xl font-bold text-2xs sm:text-xs flex items-center gap-1.5 transition-all active:scale-95 cursor-pointer shadow-2xs shrink-0 ${
                added
                  ? 'bg-zinc-950 text-white border border-border-dark ring-2 ring-primary/20'
                  : 'bg-surface-dark hover:bg-primary text-white'
              }`}
            >
              {added ? (
                <>
                  <Check className="w-3.5 h-3.5 stroke-[3] text-primary" />
                  <span className="font-bold text-white">{'Added'}</span>
                </>
              ) : (
                <>
                  <ShoppingBag className="w-3.5 h-3.5 text-white" />
                  <span>{'Add to Cart'}</span>
                </>
              )}
            </button>
          </div>
        </div>
      </article>
    );
  }

  /* ========================================================================
   * 2. GRID VIEW LAYOUT (STANDARD UNIFIED E-COMMERCE CARD)
   * ======================================================================== */
  return (
    <article 
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      className="group relative flex flex-col justify-between bg-white rounded-2xl border border-border-color/90 shadow-2xs hover:shadow-md hover:border-border-hover transition-all duration-200 overflow-hidden p-2.5 sm:p-3 gpu-smooth h-full"
    >
      {/* Top Media Container */}
      <div className="relative aspect-square w-full rounded-xl overflow-hidden bg-surface-subtle border border-border-color/60 mb-2.5">
        <Link href={`/product/${product.id}`} prefetch={false} className="block w-full h-full relative cursor-pointer z-1">
          {/* Primary Cover Image */}
          <Image
            src={imgSrc}
            alt={displayName}
            fill
            sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 25vw"
            priority={priority}
            loading={priority ? undefined : "lazy"}
            unoptimized={primaryMedia?.type === 'gif'}
            referrerPolicy="no-referrer"
            onError={() => {
              setImgSrc('https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=800&auto=format&fit=crop&q=80');
            }}
            className={`object-cover object-center transition-all duration-300 ease-out ${
              isHovered && ((hoverGif && hoverGif !== imgSrc) || secondaryImage)
                ? 'opacity-0 scale-105' 
                : 'opacity-100 group-hover:scale-105'
            }`}
          />

          {/* Hover Animated GIF Preview - Only mounted on hover to prevent massive page load delay */}
          {isHovered && hoverGif && hoverGif !== imgSrc && (
            <Image
              src={hoverGif}
              alt={`${displayName} - Animated GIF Preview`}
              fill
              unoptimized
              sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 25vw"
              referrerPolicy="no-referrer"
              className="object-cover object-center absolute inset-0 transition-all duration-300 ease-out opacity-100 scale-105"
            />
          )}

          {/* Secondary Alternate Image on Hover - Only mounted on hover */}
          {isHovered && !hoverGif && secondaryImage && (
            <Image
              src={secondaryImage}
              alt={`${displayName} - Alternate View`}
              fill
              sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 25vw"
              referrerPolicy="no-referrer"
              className="object-cover object-center absolute inset-0 transition-all duration-300 ease-out opacity-100 scale-105"
            />
          )}
        </Link>

        {/* Top-Left: Badge Stack (Discount, Flash, Trending, Best Deal, New) */}
        <div className="absolute top-2 left-0 z-20 flex flex-col items-start gap-1 pointer-events-none">
          {discountPercent && (showDiscountBadge !== false) && (product.showDiscountBadge !== false) && (
            <span className="px-2 py-0.5 rounded-e-md bg-primary text-white text-xs sm:text-sm font-bold flex items-center gap-1 shadow-md">
              <span className="font-semibold text-xs sm:text-xs">{'Save'}</span>
              <span className="text-xs font-bold">৳</span>
              <span className="font-extrabold">{savingsAmount > 0 ? savingsAmount : `${discountPercent}%`}</span>
            </span>
          )}
          {product.isFlashDeal && (showFlashBadge !== false) && (product.showFlashBadge !== false) && (
            <span className="px-1.5 py-0.5 rounded-md bg-amber-500 text-white text-2xs font-bold uppercase tracking-wider shadow-xs flex items-center gap-0.5">
              <Flame className="w-2.5 h-2.5 fill-current text-white" />
              <span>FLASH</span>
            </span>
          )}
          {product.isTrending && !product.isFlashDeal && (showTrendingBadge !== false) && (product.showTrendingBadge !== false) && (
            <span className="px-1.5 py-0.5 rounded-md bg-orange-600 text-white text-2xs font-bold uppercase tracking-wider shadow-xs">
              🔥 TRENDING
            </span>
          )}
          {product.isBestDeal && !product.isFlashDeal && !product.isTrending && (showHotDealBadge !== false) && (product.showHotDealBadge !== false) && (
            <span className="px-1.5 py-0.5 rounded-md bg-emerald-600 text-white text-2xs font-bold uppercase tracking-wider shadow-xs">
              🏷️ HOT DEAL
            </span>
          )}
          {product.isNew && !product.isFlashDeal && !product.isTrending && !product.isBestDeal && (showNewBadge !== false) && (product.showNewBadge !== false) && (
            <span className="px-1.5 py-0.5 rounded-md bg-surface-dark text-white text-2xs font-bold uppercase tracking-wider shadow-xs">
              ✨ NEW
            </span>
          )}
        </div>

        {/* Top-Right: Wishlist Button */}
        <button
          type="button"
          onClick={handleToggleWishlist}
          aria-label={inWishlist ? 'Remove from wishlist' : 'Add to wishlist'}
          className={`absolute top-2 right-2 z-20 w-7.5 h-7.5 rounded-full border transition-all duration-200 flex items-center justify-center cursor-pointer active:scale-90 ${
            inWishlist 
              ? 'bg-primary border-primary text-white shadow-xs' 
              : 'bg-white/90 backdrop-blur-xs hover:bg-white border-border-color text-text-muted hover:text-primary shadow-2xs'
          }`}
        >
          <Heart 
            className={`w-3.5 h-3.5 transition-transform ${inWishlist ? 'fill-current scale-105' : ''}`} 
          />
        </button>

        {/* Bottom Swatches overlay if multi-colors available */}
        {product.colors && product.colors.length > 1 && (
          <div className="absolute bottom-2 left-2 z-10 flex items-center gap-1 bg-white/95 px-1.5 py-0.5 rounded-full border border-border-color shadow-2xs">
            {product.colors.slice(0, 3).map((c, i) => (
              <span
                key={i}
                style={{ backgroundColor: c.hex }}
                className="w-2 h-2 rounded-full border border-border-hover"
              />
            ))}
            {product.colors.length > 3 && (
              <span className="text-2xs font-bold text-text-muted leading-none">+{product.colors.length - 3}</span>
            )}
          </div>
        )}
      </div>

      {/* Product Content Details */}
      <div className="flex flex-col flex-1">
        {/* Row 1: Category & Social-Proof Rating */}
        <div className="flex items-center justify-between gap-1 mb-1 min-w-0">
          <span className="text-2xs sm:text-xs font-bold uppercase tracking-wider text-text-muted truncate min-w-0">
            {displayCategory}
          </span>

          <div className="flex items-center gap-0.5 sm:gap-1 text-2xs sm:text-xs font-bold text-text-main bg-surface-subtle px-1.5 py-0.5 rounded-md border border-border-color shrink-0">
            <Star className="w-2.5 h-2.5 sm:w-3 sm:h-3 fill-amber-400 text-amber-500 shrink-0" />
            <span className="font-extrabold text-text-main">{product.rating ? (product.rating ?? 0).toFixed(1) : '4.8'}</span>
            <span className="text-text-muted font-semibold text-2xs hidden sm:inline">
              ({product.reviewCount ?? 28})
            </span>
          </div>
        </div>

        {/* Row 2: Product Name (Uniform 2-line clamp for neat alignment across all cards) */}
        <h3 className="text-xs sm:text-sm font-bold text-text-main line-clamp-2 leading-snug group-hover:text-primary transition-colors min-h-[2rem] sm:min-h-[2.5rem]">
          <Link href={`/product/${product.id}`} prefetch={false} className="hover:underline text-text-main font-bold">
            {displayName}
          </Link>
        </h3>

        {/* Row 3: Reassurance micro tag (In Stock) */}
        <div className="mt-1 flex items-center gap-1 text-2xs sm:text-xs text-text-muted font-medium truncate">
          <span className="w-1.5 h-1.5 rounded-full bg-emerald-600 shrink-0" />
          <span className="truncate">{'In Stock • 2-3 Days'}</span>
        </div>

        {/* Bottom Row: Price & Tactile Cart Action Button */}
        <div className="mt-auto pt-2 border-t border-border-color/60 flex items-center justify-between gap-1.5">
          {/* Price Container */}
          <div className="flex flex-col min-w-0">
            <span className="text-sm sm:text-lg font-black text-text-main font-sans tracking-tight truncate">
              {formatBDT(product.price)}
            </span>
            {product.originalPrice && product.originalPrice > product.price && (
              <span className="text-2xs sm:text-xs text-text-subtle line-through font-semibold truncate">
                {formatBDT(product.originalPrice)}
              </span>
            )}
          </div>

          {/* Professional Action Button */}
          <button
            type="button"
            onClick={handleAddToCart}
            aria-label={added ? 'Added to cart' : 'Add to cart'}
            className={`h-7 sm:h-8 px-2.5 sm:px-3 rounded-xl font-bold text-2xs sm:text-xs flex items-center gap-1 transition-all duration-200 cursor-pointer shrink-0 active:scale-95 shadow-2xs ${
              added
                ? 'bg-zinc-950 text-white border border-border-dark ring-2 ring-primary/20'
                : 'bg-surface-dark hover:bg-primary text-white'
            }`}
          >
            {added ? (
              <>
                <Check className="w-3.5 h-3.5 stroke-[3] text-primary" />
                <span className="hidden xs:inline font-bold text-white">{'Added'}</span>
              </>
            ) : (
              <>
                <ShoppingBag className="w-3.5 h-3.5 text-white" />
                <span>{'Add'}</span>
              </>
            )}
          </button>
        </div>
      </div>
    </article>
  );
});

/**
 * @file components/product/ProductGallery.tsx
 * @description Master multi-media product gallery supporting Images, Animated GIFs,
 * and high-definition In-App Video Playback with responsive controls and fullscreen lightbox.
 */

'use client';

import React, { useState, useRef, useEffect, useMemo } from 'react';
import Image from 'next/image';
import { 
  ChevronLeft, 
  ChevronRight, 
  Maximize2, 
  X, 
  Play, 
  Pause, 
  Volume2, 
  VolumeX, 
  RotateCcw, 
  Sparkles, 
  Film, 
  Layers
} from 'lucide-react';
import { Product, ProductMediaItem } from '@/types';
import { normalizeProductMedia, getYouTubeEmbedUrl, getVimeoEmbedUrl } from '@/lib/mediaUtils';

export interface ProductGalleryProps {
  images?: string[];
  media?: ProductMediaItem[];
  product?: Partial<Product> | null;
  productName: string;
}

export function ProductGallery({ images = [], media, product, productName }: ProductGalleryProps) {
  const [activeIdx, setActiveIdx] = useState(0);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isPlaying, setIsPlaying] = useState(true);
  const [isMuted, setIsMuted] = useState(true);
  const [isMainLoaded, setIsMainLoaded] = useState(false);
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const fullscreenVideoRef = useRef<HTMLVideoElement | null>(null);

  // Normalize media items (from media prop, product object, or images array)
  const galleryMedia: ProductMediaItem[] = useMemo(() => {
    if (media && media.length > 0) {
      return media;
    }
    if (product) {
      return normalizeProductMedia(product);
    }
    if (images && images.length > 0) {
      return normalizeProductMedia({ images });
    }
    return normalizeProductMedia(null);
  }, [media, product, images]);

  // Safe active index without synchronous effect setState
  const safeActiveIdx = activeIdx < galleryMedia.length ? activeIdx : 0;
  const currentItem = galleryMedia[safeActiveIdx] || galleryMedia[0];

  useEffect(() => {
    setIsMainLoaded(false);
  }, [safeActiveIdx]);

  const handlePrev = (e: React.MouseEvent) => {
    e.stopPropagation();
    setActiveIdx((prev) => {
      const cur = prev < galleryMedia.length ? prev : 0;
      return cur === 0 ? galleryMedia.length - 1 : cur - 1;
    });
  };

  const handleNext = (e: React.MouseEvent) => {
    e.stopPropagation();
    setActiveIdx((prev) => {
      const cur = prev < galleryMedia.length ? prev : 0;
      return cur === galleryMedia.length - 1 ? 0 : cur + 1;
    });
  };

  const togglePlayPause = (e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    const vid = videoRef.current;
    if (vid) {
      if (vid.paused) {
        vid.play();
        setIsPlaying(true);
      } else {
        vid.pause();
        setIsPlaying(false);
      }
    }
  };

  const toggleMute = (e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    const vid = videoRef.current;
    if (vid) {
      vid.muted = !vid.muted;
      setIsMuted(vid.muted);
    }
  };

  const youtubeEmbed = currentItem.type === 'video' ? getYouTubeEmbedUrl(currentItem.url) : null;
  const vimeoEmbed = currentItem.type === 'video' && !youtubeEmbed ? getVimeoEmbedUrl(currentItem.url) : null;

  return (
    <>
      {/* 
        Gallery Container:
        Fitted to available screen height without vertical scrolling,
        with thumbnail strip ordering reflecting exactly what the admin configured.
      */}
      <div className="flex flex-col-reverse lg:flex-row gap-4 h-[68dvh] min-h-[480px] max-h-[620px] sm:h-[74dvh] sm:max-h-[680px] lg:h-[calc(100vh-135px)] lg:max-h-[760px] w-full">
        {/* Thumbnails list (Left side on desktop, bottom strip on mobile) */}
        {galleryMedia.length > 1 && (
          <div className="flex lg:flex-col gap-3 overflow-x-auto lg:overflow-y-auto custom-scrollbar-thin shrink-0 p-1 max-h-28 sm:max-h-32 lg:max-h-full">
            {galleryMedia.map((item, idx) => {
              const isActive = safeActiveIdx === idx;
              return (
                <button
                  key={item.id || `${item.url}-${idx}`}
                  type="button"
                  onClick={() => setActiveIdx(idx)}
                  className={`relative w-20 h-24 sm:w-22 sm:h-28 lg:w-24 lg:h-30 rounded-2xl overflow-hidden shrink-0 border-2 transition-all bg-white cursor-pointer group ${
                    isActive
                      ? 'border-primary shadow-md ring-2 ring-primary/25 scale-[1.03]'
                      : 'border-zinc-200/90 hover:border-zinc-400 opacity-80 hover:opacity-100'
                  }`}
                  aria-label={`View ${item.type} ${idx + 1}`}
                >
                  {/* Thumbnail Preview */}
                  {item.type === 'video' ? (
                    <div className="w-full h-full bg-zinc-950 relative flex items-center justify-center">
                      {item.thumbnailUrl ? (
                        <Image
                          src={item.thumbnailUrl}
                          alt={item.title || `${productName} video`}
                          fill
                          sizes="96px"
                          referrerPolicy="no-referrer"
                          className="object-cover opacity-70"
                        />
                      ) : (
                        <div className="w-full h-full flex flex-col items-center justify-center bg-zinc-900 text-zinc-200">
                          <Film className="w-6 h-6 text-red-500 mb-1" />
                        </div>
                      )}
                      <div className="absolute inset-0 bg-black/40 flex items-center justify-center">
                        <div className="w-7 h-7 rounded-full bg-red-600 text-white flex items-center justify-center shadow-md group-hover:scale-110 transition-transform">
                          <Play className="w-3.5 h-3.5 fill-white ml-0.5" />
                        </div>
                      </div>
                    </div>
                  ) : item.type === 'gif' ? (
                    <div className="w-full h-full relative">
                      <Image
                        src={item.url}
                        alt={item.title || `${productName} GIF animation`}
                        fill
                        unoptimized
                        sizes="96px"
                        referrerPolicy="no-referrer"
                        className="object-cover"
                      />
                    </div>
                  ) : (
                    <div className="w-full h-full relative">
                      <Image
                        src={item.url}
                        alt={item.title || `${productName} photo ${idx + 1}`}
                        fill
                        sizes="96px"
                        referrerPolicy="no-referrer"
                        className="object-cover p-0.5"
                      />
                    </div>
                  )}
                </button>
              );
            })}
          </div>
        )}

        {/* Main Active Hero Product Stage (Video / GIF / Image) */}
        <div className="relative flex-1 h-full w-full rounded-3xl overflow-hidden bg-zinc-950 border border-zinc-200/90 shadow-xs group flex items-center justify-center">
          {/* =========================================================================
           * CASE 1: IN-APP VIDEO PLAYBACK
           * ========================================================================= */}
          {currentItem.type === 'video' ? (
            <div className="w-full h-full relative flex items-center justify-center bg-black">
              {youtubeEmbed ? (
                <iframe
                  src={youtubeEmbed}
                  title={currentItem.title || `${productName} video player`}
                  className="w-full h-full border-0"
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                  allowFullScreen
                />
              ) : vimeoEmbed ? (
                <iframe
                  src={vimeoEmbed}
                  title={currentItem.title || `${productName} vimeo player`}
                  className="w-full h-full border-0"
                  allow="autoplay; fullscreen; picture-in-picture"
                  allowFullScreen
                />
              ) : (
                <div className="relative w-full h-full flex items-center justify-center group/video">
                  <video
                    ref={videoRef}
                    src={currentItem.url}
                    autoPlay
                    loop
                    muted={isMuted}
                    playsInline
                    className="w-full h-full object-contain cursor-pointer"
                    onClick={() => togglePlayPause()}
                    onPlay={() => setIsPlaying(true)}
                    onPause={() => setIsPlaying(false)}
                  />

                  {/* Custom In-App Video Controls Bar */}
                  <div className="absolute bottom-4 left-4 right-4 bg-zinc-950/80 backdrop-blur-md rounded-2xl p-2.5 flex items-center justify-between text-white border border-white/10 shadow-xl opacity-90 group-hover/video:opacity-100 transition-opacity">
                    <div className="flex items-center gap-3">
                      <button
                        type="button"
                        onClick={togglePlayPause}
                        className="p-2 rounded-xl bg-white/15 hover:bg-white/30 text-white transition-colors cursor-pointer"
                        aria-label={isPlaying ? 'Pause' : 'Play'}
                      >
                        {isPlaying ? <Pause className="w-4 h-4 fill-white" /> : <Play className="w-4 h-4 fill-white ml-0.5" />}
                      </button>

                      <button
                        type="button"
                        onClick={toggleMute}
                        className="p-2 rounded-xl bg-white/15 hover:bg-white/30 text-white transition-colors cursor-pointer"
                        aria-label={isMuted ? 'Unmute' : 'Mute'}
                      >
                        {isMuted ? <VolumeX className="w-4 h-4" /> : <Volume2 className="w-4 h-4" />}
                      </button>

                      <span className="text-2xs font-bold text-zinc-300 hidden sm:inline-flex items-center gap-1.5">
                        <span className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
                        In-App Video Stream
                      </span>
                    </div>

                    <div className="flex items-center gap-2">
                      <button
                        type="button"
                        onClick={() => {
                          if (videoRef.current) {
                            videoRef.current.currentTime = 0;
                            videoRef.current.play();
                            setIsPlaying(true);
                          }
                        }}
                        className="p-2 rounded-xl bg-white/10 hover:bg-white/20 text-zinc-300 hover:text-white transition-colors cursor-pointer"
                        title="Replay from start"
                      >
                        <RotateCcw className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  </div>
                </div>
              )}
            </div>
          ) : currentItem.type === 'gif' ? (
            /* =========================================================================
             * CASE 2: ANIMATED GIF PLAYBACK
             * ========================================================================= */
            <div className="w-full h-full relative bg-zinc-900 flex items-center justify-center">
              <Image
                src={currentItem.url}
                alt={currentItem.title || `${productName} animated GIF`}
                fill
                unoptimized
                priority
                sizes="(max-width: 1024px) 100vw, 55vw"
                referrerPolicy="no-referrer"
                className="object-contain cursor-zoom-in"
                onClick={() => setIsFullscreen(true)}
              />
            </div>
          ) : (
            /* =========================================================================
             * CASE 3: STANDARD HIGH-RESOLUTION IMAGE
             * ========================================================================= */
            <div className="w-full h-full relative bg-zinc-50 flex items-center justify-center">
              {!isMainLoaded && (
                <div className="absolute inset-0 bg-zinc-50 flex flex-col items-center justify-center p-4">
                  <svg className="w-12 h-12 text-primary mb-1.5 opacity-80" viewBox="0 0 100 100" fill="currentColor">
                    <polygon points="50,15 90,85 10,85" />
                  </svg>
                  <span className="text-2xs font-bold text-zinc-400 uppercase tracking-widest">MAGMATI</span>
                </div>
              )}
              <Image
                src={currentItem.url}
                alt={currentItem.title || productName}
                fill
                priority
                sizes="(max-width: 1024px) 100vw, 55vw"
                referrerPolicy="no-referrer"
                onLoad={() => setIsMainLoaded(true)}
                className={`object-cover transition-opacity duration-200 ${
                  isMainLoaded ? 'opacity-100' : 'opacity-90'
                } cursor-zoom-in`}
                onClick={() => setIsFullscreen(true)}
              />
            </div>
          )}

          {/* Fullscreen Lightbox Button Top-Right */}
          <button
            type="button"
            onClick={() => setIsFullscreen(true)}
            className="absolute top-3.5 right-3.5 p-2.5 rounded-2xl bg-white/85 hover:bg-white text-zinc-800 shadow-md backdrop-blur-xs transition-all hover:scale-105 cursor-pointer z-10"
            title="Full Screen View"
            aria-label="Expand fullscreen"
          >
            <Maximize2 className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Fullscreen Lightbox Modal (Supports Images, Animated GIFs, and In-App Videos) */}
      {isFullscreen && (
        <div
          className="fixed inset-0 z-50 bg-black/95 flex flex-col items-center justify-center p-4 backdrop-blur-md animate-fade-in"
          onClick={() => setIsFullscreen(false)}
        >
          {/* Close Button */}
          <button
            type="button"
            onClick={() => setIsFullscreen(false)}
            className="absolute top-5 right-5 p-3 rounded-full bg-white/10 hover:bg-white/20 text-white transition-colors cursor-pointer z-50"
            aria-label="Close fullscreen"
          >
            <X className="w-6 h-6" />
          </button>

          {/* Media Lightbox Stage */}
          <div
            className="relative w-full h-full max-w-6xl max-h-[88dvh] flex items-center justify-center"
            onClick={(e) => e.stopPropagation()}
          >
            {currentItem.type === 'video' ? (
              <div className="w-full max-w-4xl aspect-video relative rounded-2xl overflow-hidden bg-black shadow-2xl border border-zinc-800">
                {youtubeEmbed ? (
                  <iframe
                    src={youtubeEmbed}
                    title={currentItem.title || `${productName} fullscreen video`}
                    className="w-full h-full border-0"
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                    allowFullScreen
                  />
                ) : vimeoEmbed ? (
                  <iframe
                    src={vimeoEmbed}
                    title={currentItem.title || `${productName} fullscreen vimeo`}
                    className="w-full h-full border-0"
                    allow="autoplay; fullscreen; picture-in-picture"
                    allowFullScreen
                  />
                ) : (
                  <video
                    ref={fullscreenVideoRef}
                    src={currentItem.url}
                    controls
                    autoPlay
                    className="w-full h-full object-contain"
                  />
                )}
              </div>
            ) : currentItem.type === 'gif' ? (
              <div className="relative w-full h-full flex items-center justify-center">
                <Image
                  src={currentItem.url}
                  alt={currentItem.title || productName}
                  fill
                  unoptimized
                  sizes="100vw"
                  referrerPolicy="no-referrer"
                  className="object-contain"
                />
              </div>
            ) : (
              <div className="relative w-full h-full flex items-center justify-center">
                <Image
                  src={currentItem.url}
                  alt={currentItem.title || productName}
                  fill
                  sizes="100vw"
                  referrerPolicy="no-referrer"
                  className="object-contain"
                />
              </div>
            )}

            {/* Navigation Arrows */}
            {galleryMedia.length > 1 && (
              <>
                <button
                  type="button"
                  onClick={handlePrev}
                  className="absolute left-2 sm:left-4 top-1/2 -translate-y-1/2 p-3 rounded-full bg-white/15 hover:bg-white/30 text-white transition-all cursor-pointer z-40"
                  aria-label="Previous media"
                >
                  <ChevronLeft className="w-8 h-8" />
                </button>
                <button
                  type="button"
                  onClick={handleNext}
                  className="absolute right-2 sm:right-4 top-1/2 -translate-y-1/2 p-3 rounded-full bg-white/15 hover:bg-white/30 text-white transition-all cursor-pointer z-40"
                  aria-label="Next media"
                >
                  <ChevronRight className="w-8 h-8" />
                </button>
              </>
            )}

            {/* Bottom Status Indicator */}
            <div className="absolute bottom-3 left-1/2 -translate-x-1/2 px-4 py-1.5 rounded-full bg-white/10 backdrop-blur-md text-white text-xs font-bold border border-white/10 flex items-center gap-2 pointer-events-none">
              <span className="uppercase tracking-wider text-2xs text-zinc-300">
                {currentItem.type.toUpperCase()}
              </span>
              <span>•</span>
              <span>{activeIdx + 1} / {galleryMedia.length}</span>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

