        body: JSON.stringify({
          phone: order.phone,
          message: msg,
          type: 'status_change',
          orderId: order.id,
        }),
      })
        .then((res) => res.json())
        .then((resData) => {
          store.addLog({
            channel: 'sms',
            eventType: 'status_change',
            recipient: order.phone,
            status: resData.sent ? 'sent' : resData.skipped ? 'skipped' : 'failed',
