NEXT_PUBLIC_CLOUDINARY_UPLOAD_PRESET=${state.CLOUDINARY_UPLOAD_PRESET}

# 2. Google Gemini AI Engine
GEMINI_API_KEY=${state.GEMINI_API_KEY}
