export const useSiteSettingsStore = create<SiteSettings>()(
  persist(
    (set) => ({
      ...defaultSettings,
      updateSettings: (newSettings) => set((state) => ({ ...state, ...newSettings })),
      resetSettings: () => {
        if (typeof window !== 'undefined') {
          try {
            localStorage.removeItem('magmati-mart-site-settings');
            useSiteSettingsStore.persist?.clearStorage();
          } catch (e) {
            console.error('Error clearing site settings cache:', e);
          }
        }
        set(() => ({
          ...defaultSettings,
          heroSlides: JSON.parse(JSON.stringify(defaultHeroSlides)),
          sectionLayouts: JSON.parse(JSON.stringify(defaultSectionLayouts)),
        }));
      },
      addHeroSlide: (slideData) => {
        const newSlide: HeroSlideConfig = {
          ...slideData,
          id: `slide-${Date.now()}`,
        };
        set((state) => ({
          heroSlides: [...state.heroSlides, newSlide],
        }));
      },
      updateHeroSlide: (id, slideData) => {
        set((state) => ({
          heroSlides: state.heroSlides.map((s) => (s.id === id ? { ...s, ...slideData } : s)),
        }));
      },
      deleteHeroSlide: (id) => {
        set((state) => ({
          heroSlides: state.heroSlides.filter((s) => s.id !== id),
        }));
      },
      reorderSections: (newSections) => set({ sectionLayouts: newSections }),
      moveSection: (index, direction) => {
        set((state) => {
          const newLayouts = [...state.sectionLayouts];
          const targetIndex = direction === 'up' ? index - 1 : index + 1;
          if (targetIndex < 0 || targetIndex >= newLayouts.length) return state;
          const temp = newLayouts[index];
          newLayouts[index] = newLayouts[targetIndex];
          newLayouts[targetIndex] = temp;
          return { sectionLayouts: newLayouts };
        });
      },
      toggleSection: (id) => {
        set((state) => ({
          sectionLayouts: state.sectionLayouts.map((sec) =>
            sec.id === id ? { ...sec, enabled: !sec.enabled } : sec
          ),
        }));
      },
      deleteSection: (id) => {
        set((state) => ({
          sectionLayouts: state.sectionLayouts.filter((sec) => sec.id !== id),
        }));
      },
      addSection: (section) => {
        set((state) => ({
          sectionLayouts: [...state.sectionLayouts, section],
        }));
      },
      updateSection: (id, updates) => {
        set((state) => ({
          sectionLayouts: state.sectionLayouts.map((sec) =>
            sec.id === id ? { ...sec, ...updates } : sec
          ),
        }));
      },
      updateSectionPreset: (id, preset) => {
        set((state) => ({
          sectionLayouts: state.sectionLayouts.map((sec) =>
            sec.id === id ? { ...sec, preset } : sec
          ),
        }));
      },
      updateSectionTitle: (id, name) => {
        set((state) => ({
          sectionLayouts: state.sectionLayouts.map((sec) =>
            sec.id === id ? { ...sec, name } : sec
          ),
        }));
      },
      addCombo: (comboData) => {
        const newCombo: ComboConfig = {
          ...comboData,
          id: `combo-${Date.now()}`,
        };
        set((state) => ({
          combos: [...(state.combos || []), newCombo],
        }));
      },
      updateCombo: (id, comboData) => {
        set((state) => ({
          combos: (state.combos || []).map((c) => (c.id === id ? { ...c, ...comboData } : c)),
        }));
      },
      deleteCombo: (id) => {
        set((state) => ({
          combos: (state.combos || []).filter((c) => c.id !== id),
        }));
      },
      toggleCombo: (id) => {
        set((state) => ({
          combos: (state.combos || []).map((c) => (c.id === id ? { ...c, enabled: !c.enabled } : c)),
        }));
      },
      addB1G1Offer: (offerData) => {
        const newOffer: B1G1Config = {
          ...offerData,
          id: `b1g1-${Date.now()}`,
        };
        set((state) => ({
          b1g1Offers: [...(state.b1g1Offers || []), newOffer],
        }));
      },
      updateB1G1Offer: (id, offerData) => {
        set((state) => ({
          b1g1Offers: (state.b1g1Offers || []).map((o) => (o.id === id ? { ...o, ...offerData } : o)),
        }));
      },
      deleteB1G1Offer: (id) => {
        set((state) => ({
          b1g1Offers: (state.b1g1Offers || []).filter((o) => o.id !== id),
        }));
      },
      toggleB1G1Offer: (id) => {
        set((state) => ({
          b1g1Offers: (state.b1g1Offers || []).map((o) => (o.id === id ? { ...o, enabled: !o.enabled } : o)),
        }));
      },
    }),
    {
      name: 'magmati-mart-site-settings',
      version: 10,
      migrate: (persistedState: any, version: number) => {
        if (!persistedState.sectionLayouts || version < 9) {
          persistedState.sectionLayouts = defaultSectionLayouts;
        } else {
          persistedState.sectionLayouts = persistedState.sectionLayouts.filter((s: any) => s.id !== 'curated_emporiums');
          const existingIds = new Set(persistedState.sectionLayouts.map((s: any) => s.id));
          for (const defSec of defaultSectionLayouts) {
            if (!existingIds.has(defSec.id)) {
              persistedState.sectionLayouts.push(defSec);
            }
          }
          for (const sec of persistedState.sectionLayouts) {
            if (sec.id === 'combo_products' || sec.id === 'buy1_get1') {
              sec.enabled = true;
            }
          }
        }
        if (!persistedState.combos || persistedState.combos.length === 0 || version < 10) {
          persistedState.combos = defaultSettings.combos;
        }
        if (!persistedState.b1g1Offers || persistedState.b1g1Offers.length === 0 || version < 10) {
          persistedState.b1g1Offers = defaultSettings.b1g1Offers;
        }
        return persistedState;
      },
    }
  )
);

/**
 * @file store/useVoucherStore.ts
 * @description Centralized Voucher & Coupon Management Store with Advanced Conditions.
 * Supports:
 * - Dynamic vouchers list (Managed by Admin)
 * - User voucher collection & persistence
 * - Smart validation engine (Maximum uses per customer, spend limits, overall budget, login requirements)
 * - Auto-removal of expired vouchers after admin-configured number of days
 */

'use client';

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export interface Voucher {
  id: string;
  code: string;
  title: string;
  titleEn?: string;
  condition: string;
  conditionEn?: string;
  badge: string;
  badgeEn?: string;
  expiresAtEn?: string;
  descriptionEn?: string;
  discountType: 'fixed' | 'percentage' | 'free_shipping';
  discountValue: number; // e.g. 200 for ৳200, 10 for 10%
  minSpend: number; // e.g. 1500
  maxDiscount?: number; // for percentage, e.g. 500
  paymentMethodRequirement?: 'all' | 'bkash' | 'nagad' | 'card' | 'cod';
  applicableCategory?: string; // 'all' or category name
  requiresLogin?: boolean;
  expiresAt?: string;
  isActive: boolean;
  bgGradient?: string;
  claimedByUsers: string[]; // user emails or 'guest'

  // Advanced Conditions
  maxUsesPerCustomer?: number; // e.g. 1 or 2 uses max
  maxDiscountSpendPerUser?: number; // max discount in BDT a single user can get from this code
  totalDiscountBudget?: number; // overall total budget allocated for this voucher, e.g. 50000
  usedDiscountBudget?: number; // accumulated total discount given by this voucher
  autoRemoveDaysAfterExpiry?: number; // number of days after expiry to automatically hide/remove, e.g. 3

  usedByCount?: { [userEmailOrGuest: string]: number }; // tracks how many times each user used it
  userAccumulatedDiscounts?: { [userEmailOrGuest: string]: number }; // tracks total discount amount each user got
}

export interface VoucherValidationOptions {
  paymentMethod?: string;
  isLoggedIn?: boolean;
  userEmail?: string;
  categoryNames?: string[];
  categories?: string[];
}

export interface VoucherValidationResult {
  isValid: boolean;
  discountAmount: number;
  isFreeShipping: boolean;
  message: string;
  voucher?: Voucher;
}

interface VoucherState {
  vouchers: Voucher[];
  userClaimedCodes: string[]; // List of claimed coupon codes
  claimVoucher: (voucherIdOrCode: string, userEmail?: string) => {
    success: boolean;
    message: string;
  };
  isVoucherClaimed: (voucherIdOrCode: string, userEmail?: string) => boolean;
  applyAndValidateVoucher: (
    code: string,
    subtotal: number,
    deliveryFee: number,
    options?: VoucherValidationOptions
  ) => VoucherValidationResult;
  redeemVoucher: (code: string, userEmail?: string, discountAmount?: number) => void;
  addVoucher: (voucher: Omit<Voucher, 'id' | 'claimedByUsers'>) => void;
  updateVoucher: (id: string, data: Partial<Voucher>) => void;
  toggleVoucherStatus: (id: string) => void;
  deleteVoucher: (id: string) => void;
  resetVouchersToDefault: () => void;
  getVisibleVouchers: () => Voucher[]; // helper to get vouchers not auto-removed after expiration
  maxVouchersPerOrder: number;
  setMaxVouchersPerOrder: (val: number) => void;
}

